/* 令和3年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r03.committeeSessions.push(...[{"id":"r03-20211130-7","meetingId":"r03-cm11","date":"2021年11月30日","dateIso":"2021-11-30","committee":"厚生委員会","time":"午前１０時００分～午後 ０時１９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件整理しています。","topics":[{"id":"topic-01","title":"調査事項を聴取いたします。 初めに、(1)品川区がん情報ホームページの開設","agenda":"調査事項を聴取いたします。 初めに、(1)品川区がん情報ホームページの開設","exchanges":[{"speaker":"せお委員","kind":"確認","question":"２点ほど確認なのですけれども、目的のところで、「区民、地域の支援者や医療従事者にとって利用しやすく」とあるのです。２点目が、内容の(2)のところに、そこら辺を少し説明を求めました。","respondent":"高山健康課長","answer":"そうしたものを、相談先のご紹介などもこのホームページの中には順次発信していく予定でおりますので、そうしたものも１つ想定しています。今のお答えにつながるところですが、相談・支援の内容としましては、検索しやすいものとなっております。","id":"exchange-001"},{"speaker":"せお委員","kind":"質問・要望","question":"若年層への働きかけを積極的に行っていただきたいのですけれども、そこら辺の区のお考えを聞かせていただきたいのが１点です。こちらに関しては、どのようにホームページに載せる予定なのか、そこも説明を求めました。","respondent":"高山健康課長、鷹箸保健予防課長","answer":"先ほどご説明いたしました品川区がん対策推進計画とリンクといいますか、まず、このホームページの中ではしっかりと掲載しています。そうしたものの中で、区民の方々にご紹介するに値する有用な情報などがありましたら… 現在のところ、積極的勧奨の差し控えについてで止まっている部分もありますので、早急にその内容を変更していきたいと考えています。","id":"exchange-002"},{"speaker":"せお委員","kind":"意見","question":"ホームページのほうは、せっかく作成するホームページですので、中身が少しずつでも充実していくよう、検討をお願いしたいと思います。子宮頸がんワクチンのほうも、様々取り組んでいただいているようですので、引き続き、４月から再開できるように取組をお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"家族としてどう接したらいいか、様々な相談を受けるという、このがん相談支援センターの役割が発揮できるといいなと思っているのです。その辺のところもホームページのご紹介の中では強調していただけたらいいかなという思いがするのですけれども、いかがか尋ねました。","respondent":"高山健康課長","answer":"ご紹介のがん相談支援センターにつきましては、先ほどご説明申し上げましたがん対策推進計画の中にも、患者やその家族への支援を推進するという中で。","id":"exchange-004"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"そこで相談に乗ってくださる方も、かなりのキャリアのある方がされているので、ぜひ活用されるような方向でよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１点だけ、今の質問に近いこと。そこら辺の連携関係というのはどうなのかなということだけお聞きしたい。","respondent":"高山健康課長","answer":"その後、そういったところも、きちんと区の中で情報がつながっていけるような形でリンクを貼ることを予定しています。継続的に見直しを図りつつ、使いやすく、支援によりつながりやすい仕組みとしてまいりたいと考えております。","id":"exchange-006"},{"speaker":"若林委員","kind":"意見","question":"１つだけ。重要性も鑑みて、そこら辺を少し説明を求めました。","respondent":"高山健康課長","answer":"考えられるのは、なるべく上位の階層で、このホームページにアクセスしていただけるような位置づけにしてまいりたいと考えております。","id":"exchange-007"},{"speaker":"若林委員","kind":"質問・要望","question":"いずれにしても、立ち上がって、また、区民の皆様、また私たちも見て、いわゆる改善をしっかりやっていただければいいなという要望です。今後とも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"}]},{"id":"topic-02","title":"品川区の新型コロナウイルス感染症にかかるワクチン接種状況","agenda":"品川区の新型コロナウイルス感染症にかかるワクチン接種状況","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"質問はないですけれども、（追加接種実施計画の）６の会場の6)と7)の住所は逆だと思います。それだけです。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"大変失礼しました。","id":"exchange-009"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"表２の児童福祉施設というのは、保育園かなというのは思い浮かぶのですけれども、ほかにあるのかということを伺いたいです。クラスターが発生した際、どのような対応をされてきたのかということを伺いたいと思います。","respondent":"鷹箸保健予防課長","answer":"ただ、高齢者福祉施設については、医師会の出張ＰＣＲ検査という形で医師会の先生にお願いしたりということで対応してまいりました。そうすると、その家族に検査をして、必要な検査対象をどんどん広げていくように対応してまいりました。","id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"第３波で多かった理由がもし分かれば伺いたいです。４ページの抗体カクテル療法ですけれども、これは、区民の方がカクテル療法を受けたという件数なども分かるのか尋ねました。","respondent":"鷹箸保健予防課長","answer":"これまでの人数に対して、どのような年齢層等についてという、先ほどご説明したとおりになります。３０代、４０代で、ここで亡くなられた方については第３波のときの高齢者層に多かったという状況になります。","id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問","question":"活かす上での第６波に向けての調整というところで、本当に対応していけないなと、命も守れないと思います。協議はどれぐらいの頻度で、どのような方々で、どのような情報共有をされたのかということを伺いたいのです。","respondent":"鷹箸保健予防課長","answer":"例えば、両医師会の先生方と具体的に今の感染者の状況や、自宅療養者に対してどのような対応をしているということについては個々に。","id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"第６波に向けた医療体制というところで話し合われているということですか。第５波まで、品川区内にはどれだけ受け入れられる病床があって、第６波でそれがどうなっていくのかということが、もし分かれば伺いたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問","question":"やる時期が近くなってから、どうなのか。〔「言えないのだ」と呼ぶ者あり〕 〔「モニタリングだと言っている」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、品川区のＰＣＲ検査というのは、１日何件できる体制があるのか。感染が急拡大したときに検査できる体制ができているのか、伺いたいと思います。","respondent":"鷹箸保健予防課長","answer":"１日何件という形で整備しているわけではありませんので、今後は確実に実施してまいりますので、数百件の規模でできると認識しております。","id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私たちが求めていたところでしたので本当によかったなと思いますし、とても分かりやすいなと思っているのです。これだけの医療機関に対応していただいて、そして、また感染が広がった場合には、ＰＣＲ検査センターを開くということでいいのか尋ねました。","respondent":"鷹箸保健予防課長","answer":"確かに１日１０件やれば、１０６か所で１,０６０人ということになります。お話をしておりますので、そのような場合には、また迅速にこれまでの対応がとれるものと考えております。","id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"第６波に向けて、このような対策を打っていくということを、もう少し見える形で区民に示していっていただきたいなと思うのです。１００件以上行って、どう体制を考えているのか、伺いたいと思います。","respondent":"鷹箸保健予防課長","answer":"せんだってコロナに関するホームページを大幅に変更しましたが、区民の方への広報、普及啓発を強化していくことを考えております。実は８月２７日から１週間ぐらいで埋まってしまったのですが、大田区が選ばれておりまして、いち早い症例の対応を経験しております。","id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ワクチンが広がっているからこそ、ワクチンを打てない方や打っていない方、ぜひそうした体制強化というところは引き続きやっていただきたいです。もう少し数字なども見える形で明らかにしてほしいなと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"質問","question":"それで、死因が直接コロナでない患者が３１.８％いたということなのだけれども、これはこれで、必ずそういう人が出てくるわけではないですか。先ほど、１６時間というお話があったけれども、１６時間なんて、このようなことはマスコミがどんどん騒ぐではないか尋ねました。","respondent":"鷹箸保健予防課長","answer":"最低１か月に１回、どのように対応してよいか分からなかった関係で、非常に問題のある事案がありましたけれども。Ｎ９５のマスクやゴーグル、区内では介護事業者、全て行っていただいていると認識しています。","id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"質問","question":"ワクチン供給など、そのようなことは絶対に大丈夫か尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ワクチンについて、現状、今までの期限が残っている分が、もう区に在庫としてありますので、その辺りも分かりやすく、安心していただけるような広報に努めてまいります。","id":"exchange-020"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"必ずやってほしいのは、やはり医療関係も行政側が一番中心でしょうから、ぜひしていただきたい。それだけ伺っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"高橋（し）委員","kind":"質問","question":"先ほど、国や都は大規模接種会場をやらないのでしょうかと言ったら、東京都のほうが大規模接種会場をやるのではないかというお話があるのです。８か月後なので、現状でどうか、説明を求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長、鷹箸保健予防課長","answer":"現状、少なくとも８か月になる前にお手元に届くように発送準備を進めておりますので、その辺りはクリアにできるだろうと考えております。国がやりますということで方針を切り替えましたので、１・２回目に職域接種をやったところは… 陽性者数が多かったのは、福祉施設が５５人、医療機関が４２人、企業が３６人、塾が３１人。これらが上から４つです。","id":"exchange-022"},{"speaker":"せお委員","kind":"質問・要望","question":"その１の５ページなのですけれども、もし第６波が起こったときに、またこういった体制でやっていくのかというところを確認したいのが１点です。この下にも書いていますけれども、訪問看護師というのは、医師会の訪問看護ステーションということで調整をしているのか尋ねました。","respondent":"鷹箸保健予防課長","answer":"第６波へ向けての応援体制ですが、この第５波までに経験した内容、検討はしております。医師会の訪問看護ステーションもですけれども、それ以外の訪問看護ステーションについても、医師会から声をかけていただいているという状況です。","id":"exchange-023"},{"speaker":"せお委員","kind":"質問・要望","question":"そちらを活用していただきたいなというのは、以前も申し上げましたけれども、そこを要望したいと思います。ほかのところもお忙しいですけれども、いろいろなところと協力していただいて、訪問をしていただきたいと、そこも要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"少し伺いたいのが、この資料の２ページなのですけれども、多いところでは何人ということでご説明いただきました。第３波のほうが死亡者が多かったということなのですけれども、第３波は何人ぐらいの死亡者だったのか、分かったら教えていただきたいのです。","respondent":"鷹箸保健予防課長","answer":"特に昨年の１１月などは、詳しくご説明をして、一度行った施設で次のクラスターが起きないようにという対応を具体的にしてきました。最大が１,２７５名ということなのですけれども、これ以上買うということを考えておりませんけれども、少し検討はしてみたいと考えています。","id":"exchange-025"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"これだけの経験をしてきたのに、なぜこの第５波でもそのような感じを続けられてきたのかなという思いがしているのです。どうみんなで協力し合っていくかというところで、その点と合わせて、少し伺えたらと思います。","respondent":"鷹箸保健予防課長","answer":"応援体制に関しましては、現在は既に第６波に向けたときには、すぐに全庁からも人に来ていただけるように人事部門との話合いが進んでおります。関係団体と話し合いながら、そこについては、またしっかり取り組んでまいりたいと思います。","id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/715198?Template=document&Id=3614#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":46162,"voices":91}},{"id":"r03-20211130-8","meetingId":"r03-cm11","date":"2021年11月30日","dateIso":"2021-11-30","committee":"建設委員会","time":"午前１０時００分～午前１１時４４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件整理しています。","topics":[{"id":"topic-01","title":"東中延一・二丁目、中延二・三丁目地区に関する都市計画案","agenda":"東中延一・二丁目、中延二・三丁目地区に関する都市計画案","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"周辺の地域などにポスティングなどするのかどうか伺いたいと思います。資料の中身で、こうした設定になった経緯も伺いたいと思います。","respondent":"森木密整備推進課長","answer":"実は昨年度に、１６条説明会を実施して、もう少し早い段階で地区計画の設定をやろうと考えておりました。地域の検討であったり、コロナ禍ではあるものの、手続を進めたいということで考えたところです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"一つだけ、説明会は地権者はもちろん、周りの方にもぜひ広く周知していただきたいということをお願いしたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"先ほどＱＲコードというのがありましたけれども、これは公開という意味でＱＲコードを公表するという認識でよろしいのでしょうか。ほかの地域の方も見られますか。","respondent":"森木密整備推進課長","answer":"これまでにも地区の素案の説明会であったり、ある程度説明をしてきた中での、都市計画原案としての説明会ですので。都市計画案説明会の周知につきましては、広報とホームページにも動画のＵＲＬを設置しますので、そこで見ていただくことは可能です。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問・要望","question":"自分たちの地域を見ると、密集市街地で非常に怖いので、将来をみんなで考えていこうというきっかけづくりにもなるという思いはあるのです。なので、リスクはあると思いつつも、ちょっと広げていただきたいという思いはあるのですが、その辺のお考えはいかがか尋ねました。","respondent":"森木密整備推進課長","answer":"今まで行ってきた説明会に加えて、説明会の会場に赴くことをためらわれる方に対して、補完的に説明をしたいということで設定しています。基本的には説明会で、その場で質疑応答、説明というところが一つ必要な部分かと考えていますけれども。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問・要望","question":"さっき言ったリスクはあるにせよ、広く知らせるにはとても私はいい方法だと思っているので、ぜひ今後ご研究されて、検討してほしいと求めました。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"塚本委員","kind":"質問・要望","question":"それよりも小さい土地では建物を建てないという考え方で今進めていらっしゃると思うのです。最初に６０m2のイメージ、１０坪ぐらいの家がぽこぽこと密集しているようなところを６０m2にしていくと、ちょっと教えてほしいと求めました。","respondent":"森木密整備推進課長","answer":"６０m2とある程度で切ることによって、北側の隣地境界から５０ｃｍ離すというところで、空間を空けていただくようにしております。そういったことも含めて、防災に強いということもありますし、採光や通風といった住環境にも寄与するまちが少しずつできていくと考えています。","id":"exchange-006"},{"speaker":"塚本委員","kind":"確認","question":"６０m2にしますとなると、土地をうまく１回引き取るみたいなことをやられていると思いますのですけれども、そういった対応は取られるのかどうかというのを確認させてください。","respondent":"森木密整備推進課長","answer":"それにつきましては、例えば、ＵＲで土地を１筆購入して、その周りを広げていくことによって、防災広場を設置していこうとやっている部分もあります。","id":"exchange-007"},{"speaker":"塚本委員","kind":"意見","question":"いずれにしても、しっかり目的に沿う形で土地の再編がなされるかどうかというのは、区としても積極的に取得していくという話も大事だと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"}]},{"id":"topic-02","title":"東中延一丁目１１番地区に関する都市計画案","agenda":"東中延一丁目１１番地区に関する都市計画案","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"意見書の提出がなかったということなのですが、説明会の中での質疑は、どんな質問があったのか伺いたいと思います。今回ここで計画されている建物の概要、どんな計画がされているのかを伺いたいと思います。","respondent":"森木密整備推進課長","answer":"都市計画原案の説明会の内容、状況ですけれども、地域が１１番地区と大分限られたところで、狭い街区です。その内容につきましては、防災街区整備事業の計画の中でしっかりと検討されていくと認識しております。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問","question":"以前の説明の中で、個別利用区の検討もされていくという話があったのですが、その検討がどうなっているのか伺います。Ａ３の資料で、壁面後退とかではなく、配列というのはどういうことなのか伺います。","respondent":"森木密整備推進課長","answer":"そういった形で、建物を大きく設置するというよりは、個別の利用をしていただく地区として考えております。そういった意味で、建物の配列という名前のつけ方をしているのかなと考えています。","id":"exchange-010"},{"speaker":"のだて委員","kind":"質問","question":"４階、５階ぐらいが一番いいと思うのですけれども、高くても８階までにしてほしいという声が出ています。高さを下げてほしいという声もありますけれども、いかがか尋ねました。","respondent":"森木密整備推進課長","answer":"地区の真ん中、南側にある少し飛び出たところにつきましても、個別利用区と考えています。それから１３階建て、１４階建てが高いというお話ですけれども、一つ大きく土地の有効利用が図られている結果だと考えております。","id":"exchange-011"},{"speaker":"西本委員","kind":"確認","question":"ちょっと確認なのですが、Ａ３の右側の上の図を見ると、要は、道路中心線からセットバックしてくださいという形になるのですね。権利者、その方々のご意見としては、了承いただいているという認識でよろしいのか尋ねました。","respondent":"森木密整備推進課長","answer":"今回の東中延一丁目１１番地区につきましては、土地の権利者の方が３名、借地権者の方が１３名という形になっております。先ほど言いました共同住宅に移すなり、個別利用区で取るなりという形で、今後権利変換をしていく形になります。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"今の土地利用の中で、集合住宅、共同住宅を造るとなると、それなりにお隣同士の話もあるし、かなり詰めていかなければ、弊害がいろいろ出てきます。その中で、賛成する方もいらっしゃれば、ここはそういう形のまちづくりをしていこうという意識が高まっているということでよろしいのか尋ねました。","respondent":"森木密整備推進課長","answer":"残り３名につきましても、もう既にお話をしていて、この事業として協力いただけるという形で今話を進めているところです。こちらとしても家族構成やご年齢などを様々加味して、積極的に次のステップが踏めるように案内をしていきたいと考えております。","id":"exchange-013"},{"speaker":"塚本委員","kind":"確認","question":"防災街区整備事業として、限られた事業期間の中で、共同住宅とともに個別の住宅も整備事業の中で一遍にやっていくというイメージなのですか。それを最初に確認させてください。","respondent":"森木密整備推進課長","answer":"その後、事業の中でというよりは、ご自身のタイミングで建物を建てるという形になってくるのかなとは思っています。","id":"exchange-014"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、いつでもいいというか、いつになるか、それはもうご本人次第、１０年先、２０年先というのもあり得るということなのか尋ねました。","respondent":"森木密整備推進課長","answer":"防災的にもそれほど高いリスクはないのですけれども、そういった形で、個人の方のご判断の中でそれぞれやっていただくものかなと考えております。","id":"exchange-015"},{"speaker":"塚本委員","kind":"質問・要望","question":"１階の商業施設みたいなものがそのまま残ることは、どうなっているのかなというのと、要望としてお願いしたいと思います。最初の商業施設等が今後どうなるかということについてだけ説明を求めました。","respondent":"森木密整備推進課長","answer":"建物の用途につきましては、組合でいろいろ検討されて、余剰で出てきた床を一部売却していくということも当然あろうと思います。駅にかなり近い部分がありますので、１階を商業店舗とすることも、組合の中では検討の俎上にはのるのかなと考えています。","id":"exchange-016"},{"speaker":"のだて委員","kind":"質問・要望","question":"今の質疑の中で、個別利用区は後から建てることもあり得るということで、その場合の仮移転先は、従前居住者住宅も利用できるのかどうか、そこを確認させていただきたいのと、先ほども言いました１３階建て、１４階建てが高いという声もありますので、そこは受け止めてほしいと求めました。","respondent":"森木密整備推進課長","answer":"それをしっかり有効利用をしていただければと考えていますけれども、基本的には従前居住者住宅に住んでいただくことは可能です。そこを有効活用していくことが、防災街区整備事業の中で行えることですので、組合として今はそのように検討しています。","id":"exchange-017"}]},{"id":"topic-03","title":"広町地区における土地区画整理事業の概要","agenda":"広町地区における土地区画整理事業の概要","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"これがどういうスケジュールなのか伺いたいと思います。別紙の６ページに書いてあるのですが、考え方というのですか、そこを伺いたいと思います。","respondent":"多並都市開発課長","answer":"先ほどご説明した駅前広場の３,１１４m2というのは、１階部分を立体道路として整備して、駅前広場を確保する。そういう予定でこの事業が考えられているです。","id":"exchange-018"},{"speaker":"のだて委員","kind":"質問・要望","question":"補助１６３号線を整備するまでの期間がかかってくるということで、令和１６年ということになるのか、その辺の確認をさせてほしいと求めました。交換されているのかどうかというところを見極めたいと思っているのですが、それが確認できないということになるのか尋ねました。","respondent":"多並都市開発課長","answer":"そういうことを見込むと、令和１６年３月までかかるということで予定しているものです。そして、そこの段階では示されるということですが、現時点ではまだお示しできないという考えをご説明させていただきました。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問","question":"それが、区民参加がないもとで進められていくことは問題だと思いますけれども、いかがでしょうか。十分な区民参加がないもとで新庁舎検討も進められていくと、一緒に広町の開発も進めることはやめるべきだと思いますけれども、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"内容としまして、要するに、その都市計画決定の中でもご説明させていただいたところです。品川区でもその手続の中で図書を、設計の概要という形で縦覧するということもありますので、そういう形で区民の方にご説明できることになります。","id":"exchange-020"},{"speaker":"のだて委員","kind":"質問","question":"縦覧などをやって、都市計画手続を取っていくということですけれども、それだけでは不十分だと思うのです。区役所も入ってくるということですので、全区民的な議論をしていく構えで発信していくことが必要だと思いますけれども、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"最初のＡ４の資料でご説明しましたけれども、この方針に従った事業を行っているところです。この中でも、その後にも事業の計画の形でもっと具体的に精度を上げながらご説明してきたという経緯もありますので。","id":"exchange-021"},{"speaker":"西本委員","kind":"質問","question":"何か建物を建てるのかよく分かりませんが、この図を見ると、この３つがぽんぽんぽんと離れているような気がしてしまうのです。その辺はどういう考え方で進められているのか尋ねました。","respondent":"多並都市開発課長","answer":"下にりんかい線がある関係で、今予定しているのは橋梁形式というのですか、橋の形式で渡っていこうとしています。そこについては今後の全体的な計画の中で、造成計画はしっかり作っていきたいと、そこを想定した考えでいるところであります。","id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"役所は役所の役割があるものですから、にぎわいゾーンですから、若干希望みたいのが出てきているのです。そういう形で進めてもらいたいなと思うのですが、その進め方について、何かあれば。","respondent":"多並都市開発課長","answer":"今おっしゃっていただいたような形は区でも考えていますし、一緒にコンセプトを持ちながらやっていこうということで現在それを調整している段階です。","id":"exchange-023"},{"speaker":"西本委員","kind":"質問・要望","question":"これは意見といいますか、今後１つお願いしたいのは、そういう経過を区民の方々に広めていただきたいのです。せっかくいいものを作るのですから、区民の皆さんの期待感ももうちょっと出てくるのかなと思いますので、それは研究していただければ思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"本多委員","kind":"質問","question":"資料の５ページの「ロ）道路計画」のところで、Ａ３の資料を見ると、あそこの交差点の前はまだ狭いというイメージがあるのです。スペースとか、道路があったほうがいいのではないかと思いまして、その点を説明を求めました。","respondent":"多並都市開発課長","answer":"一番左は、補助１６３号線の拡幅整備ということで、今この区画をやりますと書いてありますけれども、その下の部分だと思います。それが完成するので、それにつないだところまでやっていこうということで、これは連続した計画として捉えていただければと思います。","id":"exchange-025"},{"speaker":"本多委員","kind":"質問","question":"非常にお答えづらいことを質問してしまうのですけれども、資料の３ページに、補助２６号線の地価がここに書かれています。なぜこんなことを聞くかというと、同じ３ページにＪＲの賃貸共同住宅計画等も書かれていますけれども、イメージで結構なので説明を求めました。","respondent":"多並都市開発課長","answer":"今後の見通しですけれども、これについては、施行者に聞いても、今のところまだ分からないという言い方はしていたというのが正直なところです。補助２６号線自体は、また変わってくるかもしれませんけれども、現時点は計画の中で行っていると認識しています。","id":"exchange-026"},{"speaker":"芹澤委員","kind":"質問・要望","question":"重複の確認で大変恐縮なのですが、先ほどご説明いただいていた保留地の説明がいま一つぴんときていなくて、もう一度教えていただきたいのです。工事費を捻出するための土地ということでよろしいのか尋ねました。","respondent":"多並都市開発課長","answer":"ご説明させていただきました、今回の土地区画整理事業の目的を達成するために、この事業の中で負担すると。これについては法令に基づいたものしか負担できないことになっていますので、その範囲で負担していくということです。","id":"exchange-027"}]},{"id":"topic-04","title":"エコルとごし貸室予約の開始","agenda":"エコルとごし貸室予約の開始","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"１２月１日から町会・自治会、２月１日から環境保全活動団体ということになっているのですが、その理由を伺いたい。","respondent":"河内環境課長","answer":"これは品川区立環境学習交流施設条例第３条の環境の保全に関する活動に主体的に取り組む人材の育成および支援の中で。目的あるいは団体に応じまして、優先的にきちんと交通整理の中でお使いいただけますよう、設けたものです。","id":"exchange-028"},{"speaker":"のだて委員","kind":"質問","question":"条例に基づいてということなのですけれども、そうすると、地域交流室は、特に町会・自治会に使ってもらいたいということで整備したということか尋ねました。","respondent":"河内環境課長","answer":"地域に根ざす環境活動も大変重要という点もございまして、名前のとおり交流施設です。そういった面から地域交流室というものを造らせていただいたところです。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問","question":"金額はどのぐらい、全部でなくていいです。ある程度、具体的にこういう活動していると、何か目安になるようなものがあるのか尋ねました。","respondent":"河内環境課長","answer":"見込みかという点ですが、現在登録団体は、もう既に３団体ほどが私どものほうに名乗りを上げていらっしゃいます。学習団体とか、区民の方の環境活動を広めていただけますよう進めていきたいというところで、そういったところに目星をつけたです。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"先ほど、区内・区外で９００円とか、地域交流室のほうですか、多目的スペースのほうだったか尋ねました。","respondent":"河内環境課長","answer":"こちらにつきましては、条例の中に載っておりますので、後でご参考いただければと思います。料金設定が区民と区民以外でなされております。","id":"exchange-031"},{"speaker":"西本委員","kind":"確認","question":"もう一つ、環境保全活動団体が申請を出されて、その内容を精査して、使用できる、使用できないと決定するのは、最終的には環境課である程度確認するという認識でよろしいか尋ねました。","respondent":"河内環境課長","answer":"条例に基づきます申請用紙に基づきまして、環境課のほうで決裁いたしまして、登録を行うものです。","id":"exchange-032"},{"speaker":"のだて委員","kind":"質問・要望","question":"変更内容の(1)で、やっぱり分からないところがあるのは、どうしてもそうなってしまうのかというところを伺いたいと思います。(4)の計測管理を追加させるというところで、何件追加して、全体として何件なのかというのを伺いたい。","respondent":"栗原河川下水道課長","answer":"計測管理の実施箇所につきましては、都営浅草線の５カ所を今回変更ということで追加いたしまして、この５カ所について実施しております。続きまして、家屋調査の件数ですが、変更前が当初７１１件で、変更後は６５６件です。","id":"exchange-033"},{"speaker":"塚本委員","kind":"質問","question":"最初に、(2)のトレーラーが区役所通り、百反通りの交差点を通行できないということなのですけれども、どこをどう通ろうとするので通れないのかというところをもうちょっと詳しく教えていただけますか。","respondent":"栗原河川下水道課長","answer":"セグメントを運ぶトレーラーが干渉してしまって曲がれないということで、交通島のところに設置しておりますガードレールを一時的に撤去いたします。交差点が狭いということから、そこに交通誘導員を配置したというものです。","id":"exchange-034"},{"speaker":"塚本委員","kind":"質問","question":"では、ガードレールを外すというのは、人が通らないところですか。目黒川に早めにどんどん排出できるような形というのは、下流部よりも上流部の完成が遅くなるというのはどういう理由によるのかを説明を求めました。","respondent":"栗原河川下水道課長","answer":"上流部の工事は、既設の下水道管から上流部シールドのほうに接続する工事を実施する必要があります。その工事というのが、西品川の立坑の中から、作業員や資機材を投入しながら実施していく。","id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/212900?Template=document&Id=4338#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":29362,"voices":105}},{"id":"r03-20211130-9","meetingId":"r03-cm11","date":"2021年11月30日","dateIso":"2021-11-30","committee":"文教委員会","time":"午前１０時００分～午後 ０時２３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を56件整理しています。","topics":[{"id":"topic-01","title":"三菱鉛筆による鉛筆リサイクル事業への協力","agenda":"三菱鉛筆による鉛筆リサイクル事業への協力","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"質問は２つです。もう少し具体的に教えてもらいたいのと、協力する学校の選定というのはどのように行われたのか、２点伺いたいと思います。","respondent":"有馬庶務課長","answer":"三菱鉛筆の本社の隣がちょうど品川郵便局で、日常的に協力関係があるということで、回収も品川郵便局が行っていただけるということです。品川地区が中心でしたけれども、多くの学校が協力をして取り組みますということで、ご協力があったということです。","id":"exchange-001"},{"speaker":"吉田委員","kind":"質問","question":"伺いたいのは、どこか授業とかで生かされたらいいなと思うのですけれど、そういうことを考えておられるのかということ。この木粉が棒状肥料に変わっていくこの辺りのことがきちんと、双方の納得と合意のもとに進められたのか、その辺の経緯をもう一度伺いたいと思います。","respondent":"有馬庶務課長","answer":"もう一つ、この木粉から棒状肥料になるところは具体的には、まだ詳しくは、こちらと向こうで何か詰めていることはありません。例えば工場見学みたいなことができるのかなど、そういったことはまだ全然詰めていないので、今後の話になってくるかなと考えています。","id":"exchange-002"},{"speaker":"吉田委員","kind":"意見","question":"どういう状況にあって、これを取り組むことによってどういうふうに生かされていくのか、この取組自体がとてもよいものになるかなと思います。ぜひ今後のことも含めて、これ自体は本当にいいと思います、第一歩としてやってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"松本委員","kind":"質問","question":"すばらしい企画だと思います。これはどういった経緯で載せているのか、なぜ載っているのか、どういうご認識なのか尋ねました。","respondent":"有馬庶務課長","answer":"このパンフレット自体、三菱鉛筆が作成しておりますので、その細かい経緯まではこちらは把握していない状況です。","id":"exchange-004"},{"speaker":"松本委員","kind":"質問","question":"分かりました。これは子どもたちに配布されるものなのか尋ねました。","respondent":"有馬庶務課長","answer":"子どもたちにこの中の資源循環を理解してもらうために、１人１枚配るというふうに聞いております。","id":"exchange-005"},{"speaker":"松本委員","kind":"質問","question":"品川区の教育委員会含めて４社以外のものが出ているので、そこがどういうものなのか調べると、載っている以上は調べてほしいと求めました。その辺り、子どもだけではなく、保護者も含めた学びの機会ということについてはどのようにお考えか尋ねました。","respondent":"有馬庶務課長","answer":"今回の取組につきましては、従来使っている鉛筆の回収も当面やっていこうですので、家庭の協力が必要だということは、学校のほうも認識しております。","id":"exchange-006"},{"speaker":"松本委員","kind":"質問・要望","question":"これはあくまで要望で、パンフレットを配るというのももちろん大事ですし、通知というかお知らせの仕方をしてほしいと求めました。以上、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"つる委員","kind":"質問","question":"本当に素敵な取組だと、伺っていました。この４社の協力ということなので、回収したものを三菱鉛筆の工場か何かに届けるという、役割というのはそれだけなのか尋ねました。","respondent":"有馬庶務課長","answer":"私が三菱鉛筆から話を聞いている中では、回収に携わる、協力してくれるというふうにだけ聞いております。肥料をどこかへ持ち込むとか、そこまでの話は特段聞いていないです。","id":"exchange-008"},{"speaker":"つる委員","kind":"確認","question":"いろいろなプレスを確認すると、約１年間が、品川モデルを構築して展開していくと。どういう単位で売っているのか、１本なのか１ダースなのか分からないですけれど、幾らぐらいするものなのか尋ねました。","respondent":"有馬庶務課長","answer":"今のところ、郵便局に設置している様子を見ると、おそらくダース単位で売っているのではないかと思われます。１本単位で売っているかどうかまでは確認できませんでしたけれど、箱でカウンターに並べて販売しているというような状況は、確認しております。","id":"exchange-009"},{"speaker":"つる委員","kind":"質問","question":"こちらについては、今この仕組みの中では１１校となっていますけれども、鉛筆自体の回収というのは、学校とかでやっていたりするのですか。ちょっと余談なのですけれど、もし分かれば説明を求めました。","respondent":"有馬庶務課長","answer":"鉛筆自体は廃棄物扱いになっていて、いわゆるリサイクル品目ではないので、有価物というかリサイクル品目として集めるのは難しいらしいのです。そんな経過もあるです。","id":"exchange-010"},{"speaker":"つる委員","kind":"意見","question":"自治体間交流しているところの森とか、これは国産材のヒノキですけれども、そういったことにも展開できるのかなと思います。ぜひその辺も、教育委員会からもぜひお声を届けてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"松澤委員","kind":"意見","question":"私も大変すばらしい取組だと思ってあります。これは取りあえず品川郵便局の範囲内で１１校がスタートしますけれど、今後、全部の小学校でやる予定でしたかとの意見を述べました。","respondent":"有馬庶務課長","answer":"そこはまだ三菱鉛筆も、ここでまずやってみてということで、回収を品川郵便局の協力を得ているところもありまして、今後、うまくいけば区内に限らずいろいろ考えているようですけれども、まだ具体的に、そこについて案があるわけではございません。","id":"exchange-012"},{"speaker":"松澤委員","kind":"意見","question":"先ほど松本委員からお話がありましたけれど、親も一緒に学ぶというのは、私はすごくいいことだと思っています。ぜひそういった部分も含めて、親と学べる環境学習、そういうものを考えていただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"}]},{"id":"topic-02","title":"令和４年度入学希望申請の状況","agenda":"令和４年度入学希望申請の状況","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"なぜ減っているのかというのは、どういうふうに分析されているのでしょうか。伺いたいと思います。","respondent":"勝亦学務課長","answer":"やはり人口が増えたことによりまして、抽せん校が増えている状況で、なかなか希望するところに入れないという考え方もあるのかもしれません。ここ数年、コミュニティ・スクールの導入ですとか、そういった地域とのつながりを重視しているのではないかと考えているところです。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"この２０％のために、そういった大きな弊害をつくり続けるという選択制を、区教委はやり続けるのでしょうか。伺いたいと思います。","respondent":"勝亦学務課長、工藤指導課長","answer":"選択の幅を持ちたいという要望、希望があるという状況から、実施しているものです。先ほど申しましたコミュニティ・スクールの実施ですとか、区の町会活動の支援の中で、地域とのつながりはより強固になっていると考えています。 それに対して教員は授業改善に資するために行っているものですので、学校間の比較をするために行っているものではございません。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"だから、必要な学級数を整備するための見通しを、この３校で持っておられるのか伺いたいと思います。これまで３５人を超えた学級編成をしていた、第二延山小学校については、こちらの見通しについても伺いたいと思います。","respondent":"勝亦学務課長","answer":"来年度につきましても、こういった３５人学級の拡大もありますので、３０教室程度の増を見込んです。そういった形で受入れができるように、各校、対応の準備をしています。","id":"exchange-016"},{"speaker":"安藤委員","kind":"確認","question":"国が３５人でやると言っているわけですから、その教室の増設と併せて、そういった場合でも対応できるということでよろしいのか。もう一度伺います。","respondent":"勝亦学務課長","answer":"来年度、３０学級程度の増を見込んでいるものです。３５人学級の増、学校とも相談しながら、決定してまいりたいと考えております。","id":"exchange-017"},{"speaker":"安藤委員","kind":"確認","question":"しつこいのですけれど、３０学級ぐらい増えそうだという見通しは持っている、それは分かりました。そこだけ再度確認します。","respondent":"勝亦学務課長","answer":"３０学級程度の増を見込んで、その対応をしているです。失礼いたしました。","id":"exchange-018"},{"speaker":"松本委員","kind":"質問","question":"２０％といっても、２０％というところをもって数が少ないというのは、いささか言い過ぎた面があるのではないかと思うところです。この点について、例えばアンケート等を行って分析というのは、定期的にやられたりしているのか、お伺いしたいと思います。","respondent":"勝亦学務課長","answer":"１位が学校の教育活動、２位が学校の近さ、そういったものが重視されているという結果が出てあります。そういった意味では、友人関係ですとか近さ、そういった地域の部分が重視されているのかなというふうに捉えているところです。","id":"exchange-019"},{"speaker":"松本委員","kind":"質問・要望","question":"どういうふうに自分の進む小・中学校を選ぶか、教育委員会の中で切磋琢磨といいますか、いろいろと検討してほしいと求めました。以上、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"松澤委員","kind":"質問","question":"今の松本委員からの質問で、アンケートがとられているという中で、学校の活動であるとか、新しい、家に近いとありましたけれど、その回答は、自由に保護者が書けるものなのか、それとも選択項目があって選ぶのか、どちらなのか説明を求めました。","respondent":"勝亦学務課長","answer":"アンケートにつきましては、選択肢をこちらのほうで提示いたしまして、複数回答式という形で集計しています。","id":"exchange-021"},{"speaker":"松澤委員","kind":"質問","question":"そうすると、何といいますか、特色がよく見えていないのか、うまく伝わっていかないのか、何かそんなふうに感じてしまうのですけれども。こうやって明らかにどんどん減少していく学校について、何か教育委員会のほうで、その学校との話合いというか、そういうことは持たれるのか尋ねました。","respondent":"勝亦学務課長","answer":"児童・生徒数の状況につきまして、年度で学級を編成する中で、各学校と協議をしながら編成を進めているところです。","id":"exchange-022"},{"speaker":"松澤委員","kind":"質問","question":"今は小学校５年生からもう中学校に行って、部活をやるのですよね。そのグループ連携校という考え方の部分で、ちょっとお答えをいただけたらと思います。","respondent":"勝亦学務課長","answer":"連携校といった部分と学区の問題は、こちらはパンフレットですとか、そういった中でしっかり伝えていければと考えています。その他、また課題があるようでしたら、できるだけ公平な制度になるように研究してまいりたいと考えています。","id":"exchange-023"},{"speaker":"吉田委員","kind":"質問","question":"今、その方にどういうお便りとかが、多分、来年学校に入られる方で、何かその情報の提供の仕方がどうなのでしょうねというのが、一点あります。今の情報の出し方というのがどうなのかという、基本的なところを伺いたいと思います。","respondent":"勝亦学務課長","answer":"そちらにつきましては、住所地で指定する形になりますので、一度、全ての方に、指定の学校はここです、という通知になります。その中で併せまして、品川区では学校選択制ができますということで、そのご案内とパンフレット等をお送りしています。","id":"exchange-024"},{"speaker":"吉田委員","kind":"質問","question":"私は選択制ですという説明をしましたので、私の説明も間違っていなかったし、理解していただけたかなというふうに思います。聞き漏らしたかもしれないのですけれど、自由記述はあるのでしたか、ということを伺いたいと思います。","respondent":"勝亦学務課長","answer":"学校選択を利用された方へのアンケートにつきまして、複数の選択肢を提示していますけれども、その他ということでご記入いただける欄も用意しています。","id":"exchange-025"},{"speaker":"吉田委員","kind":"質問","question":"その他の理由が書けるのですか。「その他」だけか尋ねました。","respondent":"勝亦学務課長","answer":"失礼いたしました。その他ということで、自由記述ができる欄を設けてあります。","id":"exchange-026"},{"speaker":"吉田委員","kind":"質問","question":"今この状況がどうかというご報告ですので、現状は選択制をとっているわけですから、学校を選ばれる方もいらっしゃるのは事実です。ぜひその辺のことは、今のこのご報告とはずれるかもしれませんけれど、意見として申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"つる委員","kind":"質問","question":"いわゆる私学への進学率が３０％後半ぐらいで続いているというのは、それは評価ですか、どうですかという質疑をかつてしたことがあるのですけれど。となってくると、小学校での進学率というのは、どのぐらいになるのか尋ねました。","respondent":"勝亦学務課長","answer":"私立小学校への進学ということでのお問合せです。こちらで把握している限りでは、大体３％から５％ぐらいの人口が、それに当たるのかと見ているところです。","id":"exchange-028"},{"speaker":"つる委員","kind":"質問","question":"２１％、２０％という感じで希望される方が少なくなってきているというのは、私は先ほどの質疑を聞いていて思ったのです。だんだんそれが平準化してきているというのは、そういう部分の評価があるのかなと思うのですが、この辺りというのはどう捉えていますか尋ねました。","respondent":"勝亦学務課長","answer":"地域との連携の中で地域の方にご理解いただいて、帰ってきているという言い方はおかしいかもしれないですが、地域の学校がより選ばれているという状況なのではないかというふうに考えてあります。","id":"exchange-029"},{"speaker":"つる委員","kind":"確認","question":"ぜひ、いろいろな意味でも品川区立の小学校を選んでいただいて、入っていただいて、先ほど中学校の受験率という部分も確認させていただいたのですが。分かれば説明を求めました。","respondent":"勝亦学務課長","answer":"私学への進学率の推移ですけれども、中学校で申し上げますと、平均しますと大体３割程度が続いているような状況です。","id":"exchange-030"},{"speaker":"つる委員","kind":"質問・要望","question":"選択はしたけれども、まだそういう余地もあるのだ、というお声も伺っているところなのです。ですから、指定校変更の枠の中で行けるのであれば、そちらを選択したいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"}]},{"id":"topic-03","title":"令和３年度（４年度採用）品川区立学校教育職員採用候補者選考状況","agenda":"令和３年度（４年度採用）品川区立学校教育職員採用候補者選考状況","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今回、少ないのはなぜなのか、理由を伺いたいのが１点です。幾つか伺いますが、お願いします。","respondent":"工藤指導課長","answer":"確かに令和元年度に実施した選考は、現在、そういったことが要因の一つであるというふうに考えてあります。昨年度は感染症拡大の影響がありまして実施を見送ったということで、いわゆる周知の部分で課題があったというふうに認識しております。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問・要望","question":"先ほどの質問で、財調の算定にもならないということですか。では、都の採用の教員とどのような違う業務を行っているのか、もう少し具体的に説明してほしいと求めました。","respondent":"工藤指導課長","answer":"やはり、それぞれの先生方の理解を助けるというところでは、品川区の教育を適宜説明するという役割も担っているところです。やはり品川区が行っている一貫教育も含めた、教育施策そのものの継続、また発展には寄与していくものと考えているところです。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"さらなる少人数学級の全学年の実施の前倒し等にあてているわけですから、改めて要望させていただきたいですし、３０名にとどまらず。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"}]},{"id":"topic-04","title":"図書館システムの機能向上作業時における停止","agenda":"図書館システムの機能向上作業時における停止","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"品川区の図書館内のみの検索に絞れるように改善してもらいたいという要望があったのですが、事実どうなのかということも含めて、入っていないのか。入っていなければ、ぜひそういったところも改善していただけないかと思うのですけれど、いかがか尋ねました。","respondent":"吉田品川図書館長","answer":"そのため、一般の図書館内で検索する際には、そこも全部表示されるような、もともとそういう仕組みとしてやってまいりました。その違いのところです。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"なるほど、やはりそうなのですね。付加してもらえないかというご要望だったので、ぜひ改善してもらいたいのですけれど、いかがか尋ねました。","respondent":"吉田品川図書館長","answer":"特に他の自治体、国会図書館との連携の部分についての修正は入っておりませんので、現状どおりの仕組みのまま行く予定です。逆に、その機能があることを便利とされている方もありますので、その辺のところはまた、利用者の声等お伺いしながら、考えたいと考えています。","id":"exchange-036"},{"speaker":"安藤委員","kind":"意見","question":"区内の図書館だけとかでも検索できますというふうな、選択できるようにしてもらえないかという話なので、そこら辺は今後ぜひご検討の材料に入れてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"松澤委員","kind":"質問・要望","question":"すみません、勉強不足で教えていただきたいのですが、学校図書館システムというのは、区立図書館とネットワークでつなぐという、そのシステムでいいのか、説明を求めました。","respondent":"吉田品川図書館長","answer":"委員、ご指摘のとおりです。それに対して学校図書館システムが連携しながら、つながっておりまして、そのシステムを各学校が利用しているという形になっております。","id":"exchange-038"},{"speaker":"松澤委員","kind":"確認","question":"品川区が２３区初ということで、平成１９年に約６割の学校に学校図書館システムが整備されたと書いてあるのですけれども、そこだけ確認させてください。","respondent":"吉田品川図書館長","answer":"今、委員のご指摘のとおり、区立小学校、中学校、義務教育学校、含めまして、全ての区立の学校で、学校図書館システムは稼働しています。","id":"exchange-039"},{"speaker":"つる委員","kind":"質問","question":"私も自分自身、その辺どのぐらいなのでしょうかというやり取りを、たしか記憶しているのですが。年間でいいのですけれども、令和２年度は冊数と金額にすると、どのぐらいあったのかというのは分かりますか尋ねました。","respondent":"吉田品川図書館長","answer":"未返却の数字については、今、手元に用意してないところです。申し訳ございません。","id":"exchange-040"},{"speaker":"つる委員","kind":"質問・要望","question":"そもそも返却されないということはないのがいいのですけれど、その辺はしっかりと、数値として把握してほしいと求めました。今確認する中では、なっているかと思うのですけれど、その辺の扱いについて説明を求めました。","respondent":"吉田品川図書館長","answer":"除籍の数につきましては、ほぼ年間購入した数と同じだけのものを、現在は除籍にしています。","id":"exchange-041"}]},{"id":"topic-05","title":"武蔵小山図書取次施設の臨時休館","agenda":"武蔵小山図書取次施設の臨時休館","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"移転の理由がいま一つよく理解できないのですけれど、初めから、図の左上の場所で取次施設を開館することができなかったのかなと思うのですけれど、そこについて伺いたいと思います。","respondent":"吉田品川図書館長","answer":"その関係で、最初からそこに入ることができなかった次第です。全部整備された後、私ども取次施設が、会議室から左上の第二集会室のほうに移るという予定で進めていたところです。","id":"exchange-042"}]},{"id":"topic-06","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"１番の（１）のところで、この定義というのですか、伺いたいのが１点目です。不登校の定義を教えてもらいたいのと、後期課程というのですか、中学生の数を伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"まず様々な学校の取組と、我々のＨＥＡＲＴＳも含めた関係機関との連携と支援、また市民科での指導も当然関係しています。保護者同士、選んで別の学校に行くことも考えられるという学校選択制も、関わっているのではないかと分析しております。","id":"exchange-043"},{"speaker":"安藤委員","kind":"質問","question":"２０２１年はまだ途中なのですけれど、さらにその傾向がどうなっているのか知りたいので、分かれば同じような数字も教えていただけないかと思います。もう少し資料あるいは所管事務調査にも、ルーチン的に載せる必要があるのではないかと思うのですけれど、そこら辺はいかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"そういったパターンが変わってきたことの適用が難しいということは、聞いております。今回も１１月１日の現状でまだ何人かいますので、このお子さんたちのことを考えて、聞かれております。","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"続けて２番と３番のところの質問もしてしまいますけれど、５・７年生とありますが、目的と成果などを伺いたいと思います。ないとしたら、誰がそのような役割を担っているのか、伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"同時に不登校の対応で加配校もありますので、そこには教員が１人配置されているということで、それぞれそのような対応です。７年生については、とにかく１回は接触しますので、そういう機会として大変重要だと捉えております。","id":"exchange-045"},{"speaker":"安藤委員","kind":"質問・要望","question":"それだけにスクールカウンセラーは、その辺の人的体制の補強はぜひお願いしたいというのが、まず要望です。ぜひそういう体制をとるべきだと私は思うのですけれど、最後にご見解を伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"全ての学校では、基本的には生活指導主任が担当になっております。管理職にも必ず報告することになっておりますので、１人というよりは生活指導部会、また学校体制の中で取り組んでいると認識しております。","id":"exchange-046"},{"speaker":"吉田委員","kind":"質問・要望","question":"２番の心のケア、報告されているのか、伺いたいと思います。その中の中黒の１つ目、いじめ・差別防止、相談体制や窓口の紹介というのは、どういう窓口を紹介されているのか教えていただきたいです。","respondent":"矢部教育総合支援センター長","answer":"２点目の心のケアは、大体ほとんどの学校はこれをしているという認識で、捉えていただいて結構です。主に虐待につきましては、子ども家庭支援センターの係の方にご指導いただいたり、家庭に対応していただいているです。","id":"exchange-047"},{"speaker":"吉田委員","kind":"質問・要望","question":"でも、その先生は１人しかいらっしゃらないので、なかなか発信は難しいのですというのが、正直なお声として養護教諭の方から伺っています。もしそれらについて何かご見解があれば、伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"最後の保健室についてですが、私も学校にいたときは、養護教諭とよくお話をしていました。そこを認識しながら、そういうスタンスから、少し心の負担を軽減させてきたという経緯があります。","id":"exchange-048"},{"speaker":"松澤委員","kind":"質問","question":"２点ほどお聞きしたいのは、スクールカウンセラーの全員面談、大変だと思いますけれども。その辺について、２点お願いします。","respondent":"矢部教育総合支援センター長、有馬庶務課長","answer":"アイシグナルについては直接我々に来るものですので、大事に対応してまいりたいと考えております。土曜日にやっているということも今回情報の中にありましたので、できる限り保護者と一緒に、守っていきたいと考えております。 今年は、この２つを合わせた「しながわドリームフェスティバル」を開催できたりしておりますので、積極的にそういう面も支援していきたいと考えております。","id":"exchange-049"},{"speaker":"つる委員","kind":"質問","question":"なので、そういう部分で生かした点というのは、何かあるのでしょうか。説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"政治の働きについては６年生で行いますけれど、コロナ禍でどういうふうに政治が動くかというようなところも、取り上げられた事例があります。","id":"exchange-050"},{"speaker":"つる委員","kind":"質問・要望","question":"ぜひ眼前の危機を、危機だけにするのではなくて、それをどう捉えて、どう生かし、乗り越えていけるかという、まさに生き抜く力というのでしょうか。だから、これは別に答弁は要りません、要望で、そういう機会を今後、先ほど松澤委員との質疑でもあったので、ぜひ何か考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"私からも何点か質問させてほしいと求めました。教育委員会として具体的にどういった取組をしているのかというのもそうですし、研修等の取組などもあれば、教えてほしいと求めました。","respondent":"矢部教育総合支援センター長","answer":"総じて、コロナ禍ですので、これまでどおりの対応だけではなく、さらにお子さんに関わっていくことが、特に担任には必要なことだろうと感じています。","id":"exchange-052"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"中学生に関しては、９月の時点でもそこまで減っていないかなというのは、何か理由が分かっていれば教えてほしいと求めました。（３）を見て分かるところもあるのですけれども、親御さんから登校しないようにと言われたケースなどもあったのか、教えてほしいと求めました。","respondent":"矢部教育総合支援センター長","answer":"２点とも同じような回答になるかと思います。受験に関わることや、保護者のワクチンに対する考え方、これが合わなくて登校させていないという事例がございました。","id":"exchange-053"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"日本小児保健協会でも、自身のストレスを減らし、そして子どもへの虐待も減らすことにつながるというようなことを言っております。ＰＴＡと連携した各種講演会の実施というのが、ほかに区が保護者に対して何か発信しているようなことがあれば、それも教えてほしいと求めました。","respondent":"矢部教育総合支援センター長、有馬庶務課長","answer":"これだけ学校は感染対策をしていますという情報が伝わるように、学校だより等を発信して、少しでも安心感を与えるような取組をしております。具体になりますけれども、保健センターとつながって、保護者がご相談に行ったり… もう１点ですけれども、先ほどご紹介した立正大学の「コロナ禍のメンタルヘルスを考える」というのは、そのような取組もやっていると認識しております。","id":"exchange-054"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"本当に子どもたちの心のケアというのは、学校が対処するだけでなく、やはり親子、そして家族で支え合いながら行うべきだと考えております。ぜひ、他の自治体でもよい取組などがありましたら、随時取り入れていただきまして、子どもたちの心のケアに、より一層努めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"あくつ委員長","kind":"質問","question":"では、私から最後に１点だけ、出なかったところで伺います。どういうことが増えているのかということ、これからどのように改善していくために取り組まれているのかということを、最後にお伺いしたいと思います。","respondent":"矢部教育総合支援センター長","answer":"子ども家庭支援センターの職員を招聘して、また、これからの流れの説明をしています。は専門の子ども家庭支援センターや児童相談所というところにつないでいきたいと考えています。","id":"exchange-056"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/247429?Template=document&Id=5050#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":45794,"voices":152}},{"id":"r03-20211130-5","meetingId":"r03-cm11","date":"2021年11月30日","dateIso":"2021-11-30","committee":"総務委員会","time":"午前１０時００分～午後 ０時１６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件整理しています。","topics":[{"id":"topic-01","title":"説明に入る前に、各所管委員会における審査結果","agenda":"説明に入る前に、各所管委員会における審査結果","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"その辺のことを、この補正予算を組むに当たって検討されなかったのでしょうか。そういうところを伺いたいと思います。","respondent":"黒田財政課長","answer":"補正予算の考え方ですが、今回の補正予算は新型コロナウイルスワクチンの３回目の追加接種や、事情に応じて補正予算を組むと。今回のワクチン接種の補正予算の検討の中で、今回の第５波の後に、ワクチンの追加接種部分について編成させていただいたです。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問・要望","question":"区も非常に考えるべき時期に来ているのだと思いますけれども、その辺りの認識はしっかりおありでしょうか。もう一度、その辺の認識の点でお伺いしておきたいと思いますけれども、いかがか尋ねました。","respondent":"黒田財政課長","answer":"様々な機関と今後の体制については検討していると聞いておりますので、その中で備えていくというところであろうかと考えています。暮らしの支援についてというご質問ですが、そういった中で、きめ細かく対応させていただきたいと考えています。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問・要望","question":"私たちは一般質問でも、国に要望してほしいとか、また、区独自でやれることだからやってほしいとか、いろいろ申し上げました。意見、要望として申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"専門家によっては１月中旬に感染爆発がまた起きるのではないかという懸念をする人もいる中で、スピーディーさを求められることもあるのかなと思うのですけれども、いかがか尋ねました。","respondent":"古巻総務課長","answer":"今回３回目の接種ということになっておりますので、基本的には、３回目の接種を進めていくという方針です。接種券に関しましては、どれだけ前倒しできるかということはありますけれども、なるべく遅滞の生じないように対応していきたいと考えております。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"その時期にきちんと入ってきて、区で対応できるのですかと。そういう教訓も活かされて、今回きちんといくと思うのですが、国と都との連携というのは、もうしっかり確立されているのか尋ねました。","respondent":"古巻総務課長","answer":"連携していると認識しておりますし、そういった状況をある程度、前倒しでいろいろできるようなことも踏まえて準備をしているところです。今のところ、予定されたスケジュールで、しっかりワクチン接種を進められるように準備ができると認識しております。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"そこはしっかり、要望するところは要望してほしいと求めました。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"おくの委員","kind":"質問・要望","question":"それぞれ必要な事業なので、賛成します。営業への支援の予算、それから、検査体制を整えることへの予算もきちんと考えていただきたいという意見を申し述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]},{"id":"topic-02","title":"品川区行動計画推進会議報告書","agenda":"品川区行動計画推進会議報告書","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"第１章のところで「パートナーシップ制度」の早期導入とか、第２章のところで「男女別」制服の強制と校則の撤廃とありますけれども、こういう方向になるだろうと見ておいてよろしいのか尋ねました。","respondent":"島袋人権啓発課長","answer":"まだ答申が提示されていないというところではありますが、できるところからやっていくという考えでおります。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"行動計画推進会議の議事録を確認したのですけれども、議事要旨の改善というか、ぜひそういうのをしていただきたいというのが１つ。なので、そういった研究もしていただきたいと思うのですが、その辺について何か意見をほしいと求めました。","respondent":"島袋人権啓発課長","answer":"検討する余地はございましょうが、様々な形を取りながらも、また考えてまいりたいと思っているところです。取りあえずピックアップさせていただいたところですが、主に検討していただいた内容を書かせていただいているという経緯があります。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"もう少し議論が、どういう意見が出たとかは関心があったので、委員の方が特定されない形の議事要旨の在り方とかをしていただけたらということを要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問","question":"２ページの性的マイノリティ当事者支援に関する環境整備についてと、社会に定着することはできないのではないかと思うのですが、その辺は皆さんどのようにお考えか尋ねました。","respondent":"島袋人権啓発課長","answer":"この「など」というものの解釈を含めながら、区として何ができるかを、まず考えていただきました。あるいは、今後はそれを受けつつ、私どもの中でできるところからやってまいるです。","id":"exchange-011"},{"speaker":"須貝委員","kind":"質問・要望","question":"ぜひこういうことは進めないといけないと思うので、都や国に提言できるぐらいの書面、要望書を作れるといいなと思います。大変だと思いますが、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"たけうち副委員長","kind":"質問","question":"どういう流れになっているのかということと、３の第１章の最初の項目のところで、「実現」ではないですか。意味合いとして、「実現」ではないかという気がするのだけれども。","respondent":"島袋人権啓発課長","answer":"分かりやすいところから申し上げますと、２ページの答申内容のところですが、報告書のほうでは「実現は」になります。今後の予定のところにございました２番目の「東京都および他自治体の男女共同参画センター」の関係ですが、このようなやり取りがありますので。","id":"exchange-013"},{"speaker":"たけうち副委員長","kind":"質問・要望","question":"どうやっていけばいいのかというご心配なことも出てくるので、我々も含めて、していっていただけるような取組みをきめ細かくやっていただければ。最後、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"田中委員","kind":"意見","question":"ごめんなさい、１点だけ。認識度というか、担当課としてはどのように受け止めているのか、その辺をお知らせほしいと求めました。","respondent":"島袋人権啓発課長","answer":"全職員を対象に、人権啓発課では指針を２本つくっておりますので、そちらの研修を本年度から実施しております。来年度も実施するように、ただいま取り組んでいるところですが、しっかりと覚えていただくということを繰り返していきたいと思っているところです。","id":"exchange-015"}]},{"id":"topic-03","title":"ふるさと納税（寄附金）の返礼品追加","agenda":"ふるさと納税（寄附金）の返礼品追加","exchanges":[{"speaker":"田中委員","kind":"意見","question":"内訳はどうなっているのか。例えば、シナモロールが使われているので、そのシナモロールに対するというか、サンリオに対するお金だったり、絵本の経費だったりとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"田中委員","kind":"意見","question":"絵本というのは慎重に扱ってほしいということを思ったので、聞いたのですけれども、どういった方が関わって絵本が作成されているのかということをお知らせくださいとの意見を述べました。","respondent":"提坂税務課長","answer":"もちろんサンリオからのプランも出てまいりましたが、小さなお子さんにも大人の方にも興味を持っていただいて、区の魅力発信となるような内容という形を目指してつくってまいりました。","id":"exchange-017"},{"speaker":"渡部委員","kind":"質問","question":"だったら間口を広げて１万円にして、それでも３割は絶対入ってくるのにと僕は思うのだけれども、そういう考えはなかったのですか。頭から３万円２００人ありきで、これになってしまったという気がしてならないのだけれども、そういうところを伺いたかったのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"渡部委員","kind":"質問・要望","question":"どういう装丁で出てきて七十何万円も２００冊でかかるのか、別に表紙もぺらぺらで、普通のケント紙みたいなものでいいです。今回はこれだけの経費がかかるのだけれども、先の分の投資だと思って進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"須貝委員","kind":"提案","question":"何か対策を考えていただきたいと同時に、どうぞ国のほうに変更とかを提案していただいて、やっていただければありがたいと思います。一応、提案だけで終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"小芝委員","kind":"質問・要望","question":"こちらの絵本は対象年齢が１歳以上ということで、対象年齢といいますか、寄附をする方の年齢層はかなり固まってくるのかなと思うのです。そういった年齢層が多いのかどうかも含めて、教えていただきたいと思うのですけれども、その辺を教えてもらえますか尋ねました。","respondent":"提坂税務課長","answer":"そういうこともこちらとしては考えるところでございまして、一定の幅広い年齢層の方を対象としているということでは間違いないところです。","id":"exchange-021"}]},{"id":"topic-04","title":"「よくわかる！品川区財務諸表」の作成","agenda":"「よくわかる！品川区財務諸表」の作成","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"だから、これが一つの工夫で、これ以外にも何か工夫を考えていらっしゃるのでしょうかというのが１点です。その辺のことをお伺いしておきたいと思います。","respondent":"中山会計管理者","answer":"より分かりやすくなるかなというところで工夫をさせていただいたことが１点と、若手の職員と、このような企画にさせていただいたところです。これから積み上がっていくと、過去の実績等も反映させていけると思いますので、そういったところで工夫をしていきたいと考えております。","id":"exchange-022"},{"speaker":"田中委員","kind":"質問","question":"以前のものより本当に分かりやすくなったということで、私どもも、とても喜んでいます。周知方法について伺いたいのですけれども、なので、手に取った区民の方たちの活用法をどのように想定されているかの部分についてお知らせください。","respondent":"中山会計管理者","answer":"変換して、視覚障害の方が耳で聞いて理解しやすい内容のものについて、ホームページでアップしていきたいと考えております。会計管理室にお問い合わせいただけるように、メールアドレスとかも載せておりますので、そのときはしっかりと対応させていただければと考えています。","id":"exchange-023"},{"speaker":"田中委員","kind":"意見","question":"視覚障害者の方たちへの周知のところで、耳でも聞けるようなといった答弁がありました。ぜひそういう改善などがされたときは、視覚障害のある方たちにもその情報が届くように、何かあればお知らせ等してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"渡部委員","kind":"質問","question":"令和２年度はこうだったというところがあって、どうしてこれだけ分かりやすくなるのかと感心したのだけれども、そのきっかけを聞きたかった。説明を求めました。","respondent":"中山会計管理者","answer":"そういう視点はすごく大事かなと考えていますので、できるだけ区民の方に広く知っていただくためには、手に取っていただく。そのための工夫というのを、これからも重ねていきたいと思います。","id":"exchange-025"},{"speaker":"渡部委員","kind":"質問・要望","question":"今日は総務委員会ですから皆さんいらっしゃるので、見てみようかなというのは、すごく大事だと思うのです。少しの変化でこんなに目を引くような形になるのですから、若手の職員も交えて、全体的に変えていってほしいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"須貝委員","kind":"確認","question":"前も確認しているのですが、３月３１日以降に調整して、財調などが入ってきます。公示価格が２年に１度ぐらい変わっていきますが、小さなところで申し訳ありません、説明を求めました。","respondent":"中山会計管理者","answer":"３月３１日できっちり区切るのかというお話ですが、年度の管理としての３月３１日ということで、全てここに数値化されているところです。","id":"exchange-027"},{"speaker":"須貝委員","kind":"確認","question":"３０年前だったら坪１００万円が、今は５００万円もするかもしれないですけれども、古いまま載せるではないですか。その辺の確認を、すみません。","respondent":"中山会計管理者","answer":"失礼いたしました。取得原価時のままとなっておりますので、特段、公示価格の見直し等は行っておりません。","id":"exchange-028"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"おくの委員","kind":"確認","question":"過去の議事録を読んでいて、今は公共工事設計労務単価と比べてということになっているのですかということを、一つ確認したい。それから、工事請負契約や委託契約だけではなく、指定管理のほうにまで広げることも考えていいのではないかということをお伺いしたいと思います。","respondent":"東野経理課長","answer":"そういったところも加味しまして、今後検討はしていきたいと考えています。指定管理につきましては、指定管理のほうは行政処分という形の指定ということになりますので、こちらについての適用は現在考えておりません。","id":"exchange-029"},{"speaker":"おくの委員","kind":"質問","question":"大きい契約ばかり相手にしていたのでは、十分に全体が把握できないのではないかと思うのですが、その点、いかがなものでしょうか。問題はないとしているという見方をしているわけでは、別にないのですよねということを確かめておきたかったのですけれども。","respondent":"東野経理課長","answer":"こちらの２,０００万円以下のもののチェックにつきましては、今後実態の把握をするため、検討はしていきたいと考えています。こちらとの比較でございまして、それ以上のものでの比較というのは、現在行っておりません。","id":"exchange-030"},{"speaker":"おくの委員","kind":"質問","question":"国で定めている最低賃金と比較して、問題なければいいと考えていらっしゃるということか尋ねました。","respondent":"東野経理課長","answer":"そうです。","id":"exchange-031"},{"speaker":"おくの委員","kind":"質問","question":"そういう報酬下限額を定めるように要求していくべきだと思うのですが、そのお考えはないわけですか。しかも、そういう検討はされていないのか尋ねました。","respondent":"東野経理課長","answer":"公契約条例の中で行うべきものと考えていますが、品川区が行っている要綱では、労働報酬下限額というものは設けてございません。は設計労務単価におきましても、そこの何％というところのラインにおきまして、比較を行っているです。","id":"exchange-032"},{"speaker":"おくの委員","kind":"質問・要望","question":"そこをきちんと確実なものに、２年半もやっていれば、そこのところを真剣に何とかしようと考えてもいいのではないでしょうか。その点、いかがか尋ねました。","respondent":"東野経理課長","answer":"それから現在の最低賃金との比較という部分ですが、まず要綱に定められた基準に沿いまして、区では比較検討を行っているところです。公契約条例の検討に当たりまして、こういったサンプル的なものを集めまして、考えていきたいと思っているところです。","id":"exchange-033"},{"speaker":"おくの委員","kind":"質問・要望","question":"だからこそ、報酬の下限額を定めて、それを保証するような制度の導入がますます急がれているのだと私は思います。ですから、しかもカバーする契約の範囲を広げることを、私は意見・要望として強く求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問","question":"それが発注の期間だけというか、掲示されている時間が短いというか、一定期間が過ぎてしまうと、その資料がなくなってしまうではないですか。もう少し期間を延長してほしいという趣旨で、質問していますが、いかがか尋ねました。","respondent":"東野経理課長","answer":"本日ご説明している内容からは外れるかと思いますが、分量的に、新しいものをどんどん更新していくという形を取っているところです。期間の延長等につきましては、中でのやりくりということになりますので、少し考えさせていただければと思います。","id":"exchange-035"},{"speaker":"田中委員","kind":"質問・要望","question":"どういう条件で区が求めて、プロポーザルの期間といいますか、それでなくなってしまうのです。何か月とかでもいいので、少し……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"須貝委員","kind":"質問","question":"東京都でも、たしか製造業などはそういうことで、どうですかという書類が来ますけれども、そういうやり方はしていないのですか。説明を求めました。","respondent":"東野経理課長","answer":"それから、発注所管へ提出するような書類がありますので、それで把握をしています。下請、孫請の分まで、先ほどお話ししました労働者の確保計画書というところに記入いただくという措置を取っているものです。","id":"exchange-037"},{"speaker":"須貝委員","kind":"質問","question":"実態はどうですか、賃金はどうですか、きちんと適正に労働環境は守られていますかというのが来るのです。どうしても３者、きちんと適正にやっているのですから、そろそろ開かれた入札をしていったほうがいいのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"須貝委員","kind":"質問・要望","question":"町場に建設業者は中小でたくさんありますけれども、そういう方たちはなかなか入札に参加できないではないですか。大手がほとんど持っていってしまうのだから、その辺のところを品川区もご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"大倉委員","kind":"質問・要望","question":"何点か教えていただきたいのですが、その内訳が分かれば教えていただきたいのと、それが分かれば教えてほしいと求めました。それはどうやって確認を、いまいち理解できなかったので、教えてほしいと求めました。","respondent":"東野経理課長","answer":"令和元年度から今年で３年目ですが、大分集まってきてはおりますので、その分析についてはもう少し続けたいと思っているところです。調べることはできますので、そういったことを基に、虚偽になるかどうかという判断はできるのかなと考えています。","id":"exchange-040"},{"speaker":"大倉委員","kind":"確認","question":"サンプル数が大分少ないということで、しっかり集めて２桁ということで、分かりました。確認は来たものを見て、きちんとできていますかという確認もできるかと思うのですが、どうか尋ねました。","respondent":"東野経理課長","answer":"繰り返しになりますが、虚偽の記載があるかどうかというのは、なかなか判断するのが難しいところだと考えています。疑ってかかるというのは、事業者をという部分で、区としては難しいところかなと思います。","id":"exchange-041"},{"speaker":"大倉委員","kind":"意見","question":"もちろん、業者に提出いただいたものを疑うということよりも、しっかりチェックをするという区の責任を果たすというところで、そういった制度、システムというのを考えてもいいのかなと思いましたので、意見だけ言って終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"田中委員","kind":"質問","question":"すみません、１点だけ。今、通報の話があったのですけれども、通報の周知というのはどうやってされているのか尋ねました。","respondent":"東野経理課長","answer":"それぞれ従業員のところへ、何かしらこの情報が行っているというところでは、会社での周知だけになっておりますので、なかなか難しいかなと思います。","id":"exchange-043"},{"speaker":"たけうち副委員長","kind":"意見","question":"２３区で幾つか導入していると思うのですが、あと、そのスケジュール感というのはどんな感じで捉えているのか。プロポの設計とかというのもありますので、そこをどう考えているのかとか、その辺が分かればとの意見を述べました。","respondent":"東野経理課長","answer":"もっと課題を解消できる方法があるとか、そういったところを踏まえた形での検討を、もう少し続けていくべきかなです。最低制限価格の設計業務での対応ですが、入札ではなく随意契約ということになりますので、プロポーザルは対象とはならないものとなります。","id":"exchange-044"},{"speaker":"たけうち副委員長","kind":"意見","question":"聞き取りをやっていただいているということなので、品川区で課題をクリアできるような方式を、ぜひ検討してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"}]},{"id":"topic-06","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"田中委員","kind":"質問","question":"地方債は起債できないのではという質問に対して、改めて伺いたいのと、起債が使えないということもあるのかといったところをお知らせほしいと求めました。","respondent":"黒田財政課長","answer":"これは地方公共団体の、新庁舎整備はこの第５号事由に当たりますので、起債ができないというものではございません。まだ実際に整備計画が立っていませんので、協議を予定しているというところでございまして、まだ東京都と協議をしているものではございません。","id":"exchange-046"},{"speaker":"田中委員","kind":"質問","question":"最初の、地方債は起債できないのではという高橋しんじ議員の質問が、第５条の解釈の違いということなのですか。起債ができるかどうかの話合いがされて、何にも当たらないということもあり得るということなのか、お知らせください。","respondent":"黒田財政課長","answer":"これはできるということで、質問の趣旨とは違いますが、自治体庁舎の起債は可能です。いわゆる実質公債費比率が１８％未満であれば、基本的には、都道府県知事と協議をした上で起債をするということを考えているところです。","id":"exchange-047"},{"speaker":"田中委員","kind":"質問","question":"ごめんなさい、１点だけ。整備費等が決まらないと協議ができないということで、全てが決定してからでないと、協議自体ができないということでよろしいか尋ねました。","respondent":"黒田財政課長","answer":"整備費等が出てまいりますので、そういった検討を進める中で、随時協議をしていくということになろうかと考えております。","id":"exchange-048"},{"speaker":"田中委員","kind":"質問","question":"今、新庁舎で４００億円という大体の数字が出たわけではないですか。それで協議が始まるのではなくて、細かな数値が確定してから協議が始まるのか尋ねました。","respondent":"黒田財政課長","answer":"そういった手続きを進める中で、なかなか各年度の起債の限度額というところも協議できませんので、そういった中で協議を進めていくということになろうかと考えています。","id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/740650?Template=document&Id=2216#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":42096,"voices":153}},{"id":"r03-20211202-14","meetingId":"r03-cm12","date":"2021年12月2日","dateIso":"2021-12-02","committee":"行財政改革特別委員会","time":"午前１０時００分～午前１１時３１分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件整理しています。","topics":[{"id":"topic-01","title":"区有施設、公有地等の活用に関すること","agenda":"区有施設、公有地等の活用に関すること","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"天王洲のほうは、アートといいますか、そうした文化がだんだん広がってきたという雰囲気を感じるような状況になってきていると思うのです。老朽の状況から５年程度を暫定活用ということでしたけれども、見通しというか、考えはあるのか尋ねました。","respondent":"佐藤企画調整課長","answer":"旧東品川清掃作業所の、その後の本格活用についてのご質問です。今、様々な担当レベルで検討していますが、暫定活用期間の中で、解体も含めて、どういった施設を本格的に活用するのか、今後検討してまいります。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはりこういうスポーツ、本当に限られていて、なかなか広がる場所がないのではないかと思っているところです。そして発信できる、そして新たな方々が誕生するようなまちにしていただきたいと、要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"須貝委員","kind":"質問","question":"水辺のほうも一体として直さないと、何かバランスが悪いのかなとも思ったのですが、あくまで作業所の中だけの改修工事なのでしょうか。その２点について説明を求めました。","respondent":"佐藤企画調整課長","answer":"まさに検討しているところなのですが、まず建屋は、外部タイルが落ちてしまったり、築３０年ということも、海辺に近いということもあります。暫定活用ですので、大きな金額はかけずに、今の建屋を活かしながら使っていきたいというふうに考えてあります。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問・要望","question":"要望なのですが、５年ということはあるのですけれど、やはり皆さんが見てもいいところだなと思うような改修工事をしてほしいと求めました。せっかくやるなら、そういう検討もお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"のだて副委員長","kind":"提案","question":"今回、暫定活用の提案がされたのですけれど、こういった活用をしていこうということで検討された内容を伺えたらと思います。既に壁面アートですとか、防災倉庫、開放広場で暫定活用中ということですが、今後５年間程度、暫定活用をしていこうという検討経過について伺いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"のだて副委員長","kind":"提案","question":"公有地活用ということなので、旧荏原第四中学校のことについても伺いたいのですけれども。公有地活用という議題でやっているので伺いたいのですけれども、障害者施設などを提案していますけれども、伺いたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"公有地活用ということでこの特定事件調査になっているわけですから、今回、報告としては旧東品川清掃作業所についての説明がありましたけれども、ほかの公有地について議論する場でもあると思いますので、これはぜひ答弁ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これは今日伺ったのですけれども、平成３０年頃からというより、という話をずっとしてきたと考えています。という要望だけにしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"}]},{"id":"topic-02","title":"新庁舎に関すること","agenda":"新庁舎に関すること","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"もっと多くの皆さんのご意見を寄せていただきたいと思うところで、パブリックコメントに当たっての説明会をすべきだということも求めてきました。ですので、今からさらに周知をし、そして説明会をし、多くの意見を募る必要があるのではないかと思うのですけれども、いかがか尋ねました。","respondent":"東野庁舎計画担当課長","answer":"基本構想につきまして、改めて説明会を行うということは考えてございません。その際には、そういった説明会等につきましても、コロナの収束状況、こういったものを勘案して考えていきたいと考えています。","id":"exchange-009"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そこを引き続き私たちも求めていきたいと思いますけれども、住民の皆さんにこういう計画だということを知っていただいて、ご意見をいただく。それで、４８名の方がパブリックコメントに答えてくださったのですけれど、この数字については、区としてはどのようにお考えか尋ねました。","respondent":"東野庁舎計画担当課長","answer":"周知につきましては、こちらの基本構想（案）の４４ページにも掲げてありますとおり、１人でも多くの方に情報を届けていきたいと考えております。そういった中では、４８名１２６件という件数は、このパブリックコメントとしては有意義な数だったのではないかと感じております。","id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"コロナも今落ち着いているときですので、ぜひお願いしたいと、ここは要望にします。それと、パブリックコメントで寄せられた意見をどのように反映させたのか、そこを伺いたいと思います。","respondent":"東野庁舎計画担当課長","answer":"今後の検討状況を区民へお知らせする手段として、委員からもお話がありました説明会、そういったものも今後は考えていきたいと思っているところです。","id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"説明はぜひ丁寧にやってほしいと求めましたし、庁舎は高層にすべきでないという意見も多くある中で、それは取り入れられないのでしょうか。その理由を伺いたいと思います。","respondent":"東野庁舎計画担当課長","answer":"こちらのパブリックコメントの回答欄に書いてある部分もあるのですけれども、一定のフロア面積、一定程度の高さが必要になろうかと思います。そういったことで回答いたしまして、区民の皆様にはお知らせしています。","id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはり開発と切り離して考えていただきたいですし、そういう意見が多かったですから、そうしたことはさらに広げていっていただきたいです。もっと幅広く捉えられるだけの土地はありますので、ぜひそこは考えていくべきではないかと思うのですけれど、いかがか尋ねました。","respondent":"東野庁舎計画担当課長","answer":"こちらの内容で基本構想の策定につながってきておりますので、それについては議論をしたものとして、区としては捉えております。きちんと区の考え方を説明した上で、反映させるべきところはさせているというふうに考えておりますので、ご理解いただければと思います。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問・要望","question":"これは入った第一歩ですから、これからつくり上げていっていただきたい、まとめてほしいと求めました。意見だけ言わせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"あくつ委員","kind":"質問・要望","question":"策定委員会でも確認したのですけれど、６ページのところ、幾つかちょっと確認させてもらいます。ＮＯ.３－１４、「食堂は区民にも利用しやすい場所に配置してほしい」というところで、これも策定委員会の時に要望したのですが。","respondent":"東野庁舎計画担当課長","answer":"検討を進めるに当たりましては、大井サンピア商店街との関係ですとか、そういったところも考えていく必要があるのではないかと考えています。基本計画の中で、それらについて十分に検討していきたいと考えております。","id":"exchange-015"},{"speaker":"あくつ委員","kind":"質問","question":"では、今のが公式な見解、初めて議会への公式な見解ということで、よろしかったですねということ。もし前にお知らせいただいていたら申し訳ないのですけれども、お知らせいただければと思うのですけれど、いかがか尋ねました。","respondent":"東野庁舎計画担当課長","answer":"税務署が新庁舎に入るかということでの回答としては、正式に回答したのは今回初めてだと思われます。行政機能を集約していくという考え方のもとに、機能的なところも現在検討しておりますので、こちらの委員会で報告をしていきたいと考えています。","id":"exchange-016"},{"speaker":"あくつ委員","kind":"提案","question":"議会として何かそういうものを、ここの場でやるということでいいのですか。議会機能については提案はしますけれども、そういうことについて提案する場というのが正直ないので、これは委員長にお聞きしたほうがいいのかとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"あくつ委員","kind":"確認","question":"そういうものを、では、これからそういう場がこの委員会であると、少なくとも１回以上あるということでいいのかどうか。ちょっと確認させてください。","respondent":"つる委員長","answer":"今後、当委員会では、２月下旬にある第１回定例会の中での委員会として予定されているとき、新庁舎に関することがありますので、その場になります。当委員会においては２月下旬に、新庁舎に関することの調査の場を設けていますので、当然その場でもご意見いただけるところです。","id":"exchange-018"},{"speaker":"あくつ委員","kind":"確認","question":"そのフォローということも含めて、この委員会の中でそういう場があるということで、確認させていただきました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"確認","question":"今の確認だけさせてもらっていいですか。確認だけですけれど、１２月８日までに各会派からご意見をいただくという、その他の意見の欄も設けさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"あくつ委員","kind":"質問・要望","question":"課長が答える前に１点、確認ですけれど、うちも含めてそう思っていたかどうか。議会機能に関する、あそこにある検討様式の項目以外のところでの要望を入れるという、多分そういう認識ではなかったのかなと思うのです。","respondent":"東野庁舎計画担当課長","answer":"こちらの検討に当たりましては、資料のほうにも出ております、策定委員会の第６回、第７回、第８回で、中身について細かく検討をしてまいります。決定につきましては、パブリックコメントを受けて、９月に答申をいただいてから決定というような流れで進めたいと考えています。","id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"確認","question":"私が質問するかどうか確認をしたいのは後でやるけれども、議会の皆さんも思っていらっしゃることは付議をしていこうというつもりで、私はいます。ということで動いているという感じではないかと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"あくつ委員","kind":"確認","question":"ごめんなさい、ここでやる話ではないのですが、せっかくですから確認をさせていただきました。各会派がそういう認識でいるのかどうかも含めて、もう一回確認しておいたほうがいいのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"石田（秀）委員","kind":"質問","question":"そういうものも入れ込むのか、それは第２庁舎に入れ込むのかなど、いろいろな考え方があるではないですか。そこら辺のところ、我々も聞くけれど、どういうふうになっていくと思ったらいいのか尋ねました。","respondent":"東野庁舎計画担当課長","answer":"中小企業センターにつきましては、現在残すという方向で検討を進めておりまして、その使い方についても併せて考えていく必要があると考えています。年明け、第７回から第８回辺りには、細かいことが提示できるのではないかと思っているところです。","id":"exchange-024"},{"speaker":"石田（秀）委員","kind":"質問","question":"そうなると、そういうものも議会改革推進会議でも言うけれど、ここで２月末に１回しっかりやるというぐらいの感覚でいたほうがいい。というぐらいの感じで思っておけばいいか尋ねました。","respondent":"東野庁舎計画担当課長","answer":"議会は議会のほうで皆さんのご意見があると思いますので、この行財政改革特別委員会で、そのご意見については承りたいと思います。併せまして、先ほどもご説明させていただきましたが、どういった形が適切なのかという部分についても併せもって考えていきたいと思います。","id":"exchange-025"},{"speaker":"塚本委員","kind":"質問","question":"費用についても区民の方からもいただいていますけれども、そのイニシャルコストの４００億円ということだけが独り歩きするのでなく。庁舎維持のために、数字的なものでも見積り的なものでも出てくるとありがたいと思うのですけれど、その辺はいかがか尋ねました。","respondent":"東野庁舎計画担当課長","answer":"まさに委員がおっしゃるような形の数字的なところも、この基本計画の中で考えていくべきものだと考えています。そういったものも併せてどういった形がいいのかという部分を決める段階で、当然費用のことについてもお示ししていく必要があると考えています。","id":"exchange-026"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"すみません、もう一度確認させていただきたいのですけれども。ある程度時間が限られた中でやるわけですから、どういうふうにやっていくのが一番好ましいのかと、私は思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"せお委員","kind":"質問","question":"パブリックコメントを令和４年８月に行うとなっていますが、提出方法だったり、同じように行うのでしょうか。そこだけ説明を求めました。","respondent":"東野庁舎計画担当課長","answer":"コロナ禍の状況によって説明会の開催ですとか、あとは少人数でのワーキンググループをつくっての説明ですとか。その時期によってできることを、最大限やっていきたいと考えています。","id":"exchange-028"},{"speaker":"せお委員","kind":"質問・要望","question":"行かなくてもいいですし、ハードルが低いので、もうちょっと若い方も。そこら辺も検討しながら、次回のパブリックコメント実施を検討していただきたいなと、そこだけ要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"あくつ委員","kind":"提案","question":"何か具体的にお声を聞く、ただしパブリックコメントですから、あまり偏った意見ではパブリックではないと思うのです。私も聞きたいし、前向きな、建設的な提案として伺いたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"のだて副委員長","kind":"質問","question":"今回このパブリックコメントを受けて、基本構想を変更した部分というのはあるのか、伺いたいのと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"つる委員長","kind":"提案","question":"もし各委員からご意見があれば教えていただきたいという投げかけがあって、各委員いかがですかということに対して、発言してください。ほかの委員、今のあくつ委員のご提案に対して、ありますかとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"石田（ち）委員","kind":"意見","question":"どういうことが必要なのかというところでは、みんなどうだろうというのを、やはり分からないのですね。私も先ほど言いましたけれど、やはり説明会が大事ではないかと、一つ思うところですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"せお委員","kind":"質問・要望","question":"今、品川区でもＬＩＮＥ、Ｆａｃｅｂｏｏｋ、Ｔｗｉｔｔｅｒ、そういったこともされていますし、周知というところではそういうもの。意見の提出方法も、そちらを使うとまた結構違ってくると思うので、私はそこは要望したいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"須貝委員","kind":"意見","question":"現実、そのようなことは難しいのではないかと、私は思います。意見だけ言わせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"西村委員","kind":"意見","question":"例えば１０代の方たちからどうやって声を集めたらいいのだろうとか、今のあくつ委員のお話を聞きながら、ちょっと考えました。感想というか、意見ですとの意見を述べました。","respondent":"東野庁舎計画担当課長","answer":"生徒からのご意見を伺うといいますか、教育委員会のほうでまとめていただいたものを提案いただくようなことも、現在取り組んでいるところです。","id":"exchange-036"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"１００件を超えたりする場合もありましたので、広くお知らせして、意見を得てほしいと求めました。そうであるならばオンライン説明会などを実施していくということも必要なのではないかと考えたのですけれども、いかがか尋ねました。","respondent":"東野庁舎計画担当課長","answer":"反映されたところにつきましては、先ほども説明させていただきました、こちらの基本構想（案）の４４ページにある各項目のところです。それからオンライン説明会につきましては、なかなか発信の技術的なところも含めて、結構ハードルが高い、難しいところがあります。","id":"exchange-037"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"収まるかどうか分からない状況なので、ぜひそこは前向きに検討してほしいと求めました。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"}]},{"id":"topic-03","title":"議会閉会中継続審査調査事項","agenda":"議会閉会中継続審査調査事項","exchanges":[{"speaker":"のだて副委員長","kind":"提案","question":"先ほど聞けなかったので、旧荏原第四中学校について伺いたいと思うのですけれども。２０２３年まであと２年活用していくということですが、障害者施設などを提案していますけれども、伺いますとの意見を述べました。","respondent":"佐藤企画調整課長","answer":"旧荏原第四中学校跡の本格活用に関わる検討のご質問だと思います。委員ご指摘のとおり、地域として防災性の強化が求められる地域でありますので、そういった面も含めながら、現在検討中でおります。","id":"exchange-039"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"もともと学校の跡地ですから、広く住民参加をした検討会を行っていくとか、ワークショップなどをやるべきだと思うのですけれども、いかがでしょうか。そうすることで、地域に愛される施設になると思うのですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"渡部委員","kind":"意見","question":"私たちは今の副委員長の発言をただ聞いているだけということになってしまって、それはあまりにも委員会を私物化し過ぎていると思いますので、これ以上はやめておいたほうがいいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"石田（秀）委員","kind":"意見","question":"先ほども２月に新庁舎のことは予定として取り上げますと、それは委員長と副委員長が計画を練って、そういうことをされている委員会なのです。それだけですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/444693?Template=document&Id=6120#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":26655,"voices":91}},{"id":"r03-20211203-19","meetingId":"r03-cm12","date":"2021年12月3日","dateIso":"2021-12-03","committee":"災害・環境対策特別委員会","time":"午前１０時００分～午前１１時５２分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"私自身マンションに住んで４０年近く、その経験に基づきながら、どうなっているのかなということでお伺いします。防災訓練の中に取り込もうとしていらっしゃるのか、まず、その点をお伺いしたいと思います。","respondent":"山本防災課長","answer":"それから、うまくいっているところもあるかと考えていますが、なかなかまだ交流ができていないというところも認識しています。管理組合は非常に大きな役割を果たしていると考えていますので、どう連携を図っていくかというところは、区としても検討していきたいと考えています。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問・要望","question":"管理組合のほうから申し込んでということなのでしょうか。何％ぐらいといいますか、大ざっぱでいいのですが、お分かりになるのでしたら教えていただきたい。","respondent":"山本防災課長","answer":"管理組合のほうからご相談いただいて、いろいろ事前検討等も行いながら、実際に人を派遣するという運用を行っているところです。令和元年度を見ますと、講演件数が５件、訓練が９件、それから、相談数が２０件といった実績になってあります。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問・要望","question":"いろいろ地震の心配や水害の心配が出てきているところですから、品川区としても、かなり問題として自覚されているところだと思うのです。こうしよう、ああしようといういろいろな工夫を考えられているのではないかと思うのですが、そこら辺はいかがか尋ねました。","respondent":"山本防災課長","answer":"管理組合への対応です。先ほど、支援や訓練等の件数を申し上げましたが、もちろん管理組合独自で訓練されているところもたくさんあるということも認識しているところです。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問","question":"これは、管理組合のほうに配付されたのですか。どうでしょう。","respondent":"山本防災課長","answer":"それから、もう少し薄いものになるのですけれども、居住者向けハンドブックにつきましては、約３万９,０００部。こちらも個別に配付させていただいているところです。","id":"exchange-004"},{"speaker":"おくの委員","kind":"質問・要望","question":"そこら辺どうでしょうか。そのようなこともお考えか尋ねました。","respondent":"山本防災課長","answer":"こちらの防災ハンドブック等は、かなり中身が充実しているものだと我々も思っております。その辺りを広く普及しながら、そういった部分に対応できるよう、区としても働きかけというところをしっかり考えていきたいと思ってあります。","id":"exchange-005"},{"speaker":"おくの委員","kind":"質問","question":"そこら辺、町会・自治会との関連で、区がダイレクトにというところのお考えはいかがでしょうか。そこも少しお伺いしておきたいです。","respondent":"山本防災課長","answer":"町会や自治会等を経由しての働きかけ、両方あるかと思うのですけれども、それぞれメリットもあると思っています。地域の連携強化に資する部分がかなり大きいと考えていますので、今後のマンション対策も含めて、全般として考えていきたいと思っています。","id":"exchange-006","title":"町会・自治会支援"},{"speaker":"おくの委員","kind":"質問・要望","question":"負担の重さがあると思いますので、必ずしも町会・自治会を通さない道、ルートも排除しないようにしながらやってほしいと求めました。そういうことを要望、意見として申し上げて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007","title":"町会・自治会支援"},{"speaker":"松澤委員","kind":"質問","question":"これをどのようにやっていくのか。１５ページに振り返りがありましたけれども、行政にやっていただくのか、そこら辺を説明を求めました。","respondent":"五十嵐災害対策担当課長","answer":"実施した町会のほうも非常にいいということなので、そういったものも含めて進めていきたい。もちろんアドバイスはさせていただきたいと考えておりますが、基本的には主体である町会・自治会の方でやっていただきたいと考えております。","id":"exchange-008"},{"speaker":"松澤委員","kind":"質問","question":"それに付随する保護者も一緒に学ぶという機会が増えますので、何とか教育委員会と手を取って、そういうものも１つなのかなと個人的に思っております。そこら辺だけ説明を求めました。","respondent":"五十嵐災害対策担当課長","answer":"１２月４日の区内一斉防災訓練では、３消防署、４警察と通信連携を図っていきたいなと考えています。その訓練結果を基に検証させていただいた上で進めさせていただきたいなと考えています。","id":"exchange-009"},{"speaker":"松澤委員","kind":"質問・要望","question":"なぜなら、やはり女性の視点での配慮というのは大事だと思いますので、そこら辺がどうなっているのか教えていただきたい。非常にすばらしい取組みだと思ったので、または動画で配信するといった工夫があってもいいかなと思うのですけれども、そこら辺どうか尋ねました。","respondent":"平原防災体制整備担当課長","answer":"避難者という視点については、国の男女比率そのものが反映されると思いますので、女性も相当数入ってくると考えています。このようなレシピがありますということは啓発させていただきまして、備蓄物資の使い方が広く行き渡るように啓発してまいりたいと考えています。","id":"exchange-010"},{"speaker":"吉田委員","kind":"質問・要望","question":"見解を伺います。先に備蓄だけ伺っていいか尋ねました。","respondent":"平原防災体制整備担当課長","answer":"先ほど、資料のご説明をさせていただきましたとおり、例えば、熊本地震の際は、女性視点ということが非常に問題となった災害でございました。そういった認識を、次の災害が発生したときには、そういったことを繰り返さないようにしていきたいと考えています。","id":"exchange-011"},{"speaker":"吉田委員","kind":"質問・要望","question":"捨てるものはないと思うのですけれども、その辺はどうなのでしょうか。説明を求めました。","respondent":"平原防災体制整備担当課長","answer":"例えば、今お話のございました毛布について、毛布も当然廃棄という形ではなく、資源品として、また再利用できるという道もありますので、そういったところで活用しながら、決して廃棄して新しいものを購入することのないように、今、実際に運用させていただいているところです。","id":"exchange-012"},{"speaker":"吉田委員","kind":"質問・要望","question":"６か月などの賞味期限が来る前のものを有効利用ということで、年越しの時に、今でもあるのではないでしょうか。どうやってこれを解消していくのか、教えていただける範囲で教えてほしいと求めましたが、いかがでしょう。","respondent":"五十嵐災害対策担当課長","answer":"それと、全庁的に災害対応可能な態勢の構築という部分では、職員を約１５０名から２００名にボアアップさせて訓練に対応させています。一元化につきましては、これも前回の訓練より格段にパワーアップさせた形で訓練を進めているという状況で、課題の解消に向かっております。","id":"exchange-013"},{"speaker":"吉田委員","kind":"質問・要望","question":"若い世代が、このようなことであれば自分たちも協力できるというふうになるのではないかなと考えながら伺っていました。これは要望にとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"たけうち委員","kind":"質問","question":"区を越えて、区境の中で、そういう近隣区との連携というのですか。この書類上は１日分となっていますけれども、ある程度余裕を持って備蓄をされているのだと思うのですけれども、その辺の考え方を説明を求めました。","respondent":"五十嵐災害対策担当課長、平原防災体制整備担当課長","answer":"直近では、１１月２１日だったと思いますが、目黒川沿いのマンションで実際に訓練はなされております。区境の町会の連携ということですけれども、どのように連携していくかということは、これから研究していきたいなと考えています。 先ほど、ここでご紹介させていただきました災害救助法の考え方の１つに、現在地救助の原則というものがあります。単純計算で３６万食ですが、現状５０万食を備蓄しているところでございまして、余裕を持った備蓄としています。","id":"exchange-015"},{"speaker":"たけうち委員","kind":"質問・要望","question":"個別の状況に応じてどうすればいいのかということを考えられるような訓練も、講習になるかもしれないですけれど、大事かなと思うのです。その辺は、何か工夫されていますか尋ねました。","respondent":"五十嵐災害対策担当課長","answer":"もちろん、生活環境に応じて対応してほしいということも、加えてお伝えしています。しながわ防災体験館のほうでも、また個別にご指導していますので、そういったところをご活用いただければと考えています。","id":"exchange-016"},{"speaker":"たけうち委員","kind":"質問・要望","question":"一応要望というか、こういう時期ですから、やっていただけるとありがたいかな。要望として、終わります。","respondent":"滝澤災害対策担当部長","answer":"２階に上がれば命は助かるだろうということで、セカンドベストの逃げ方という訓練であれば、多分かなり広い範囲で参加をしていただけるのです。個別計画の作成と合わせて、逐次、防災訓練のやり方についても、地域とともに連携しながら考えていきたいと考えています。","id":"exchange-017"},{"speaker":"こんの委員","kind":"質問","question":"これは、硬いパンのことでよろしいのでしょうか。これは、備蓄として本当に必要なものなのでしょうかというのがずっとあるのですけれども、その点。","respondent":"山本防災課長、平原防災体制整備担当課長","answer":"区としましては、まず、マンション防災については、各居住者の自助、それから、居住者同士の共助で対応するのが原則だと考えています。２３区でも複数区に実績がありますので、その辺り、区としてもいろいろ研究をしています。 年齢層に応じた形での備蓄も、今、進めてあります。そういう中での位置づけでビスケットが入っているというところで、ご理解賜ればと思います。","id":"exchange-018"},{"speaker":"こんの委員","kind":"質問・要望","question":"要望で終わります。その点、もう一回、いかがか尋ねました。","respondent":"平原防災体制整備担当課長、山本防災課長","answer":"果たして、あの１つが本当に１食なのかという問題はありますけれども、まだ、私どもも、いろいろ研究は進めてあります。これからも、新商品動向をいろいろ研究させていただきまして、これに立ち止まることなく… それから、ペットの同行避難の訓練につきまして、具体的に区で実施したことはございません。そういった訓練等も行いながら、全避難所で理解が得られるよう、区としても対策を進めていきたいと考えています。","id":"exchange-019"},{"speaker":"こんの委員","kind":"質問・要望","question":"その課題の点が１つ。その辺の状況を説明を求めました。","respondent":"山本防災課長","answer":"まず人を優先にいろいろ考えていきたいというところで、ペットの受入れの部分の検討まで進んでいないというところが、一部あると認識しています。こちらにつきましては、積極的にやっていきたいと考えています。","id":"exchange-020"},{"speaker":"こんの委員","kind":"質問・要望","question":"やはり１度は実施して、同行してきたペットをどこにどのようにゲージを置いて、どうするのか。何かございましたら、答えるよう求めました。","respondent":"山本防災課長","answer":"ご案内いただいたとおり、飼い主への事前のルール周知といいますか、意識の啓発が非常に重要だと考えています。その辺りは、生活衛生課とも連携をとりながら、周知等を図っていきたいと思ってあります。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"具体的に、この防災訓練ガイドは、どういうところで、どう活用されているのか。その点について、説明を求めました。","respondent":"山本防災課長、五十嵐災害対策担当課長","answer":"被害想定の件について、私からお答えいたします。今後、こういったガイドなどの掲載も研究していきたいと思ってあります。 しながわ防災訓練ガイドにつきましては、各自治会で単独訓練を実施する場合、もしくは地区防災訓練でこのような訓練をやりたいというときの参考資料として活用いただいております。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"消火器ラリーという、町会みんなで場所を確認して、消火の訓練についての品川区の考え方を教えてほしいと求めました。意識も高まっていくというところに対しての区の働きかけや、区の意識づけというのはどのように考えられているのか、その点についても伺います。","respondent":"山本防災課長、五十嵐災害対策担当課長","answer":"私から、被害想定の最初の質問について、お答えいたします。こちらのガイドのほうには記載がございませんが、それらを合わせて活用いただけるよう、そこは周知をしていきたいと思ってあります。 私からは、スタンドパイプと消火器の件をお答えします。消防団と連携して、区としてもしっかりした初期消火、防災行動力を高めていく方法をしっかり伝えていきたいと考えています。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは、町会から希望があったものを配付するという形になっているために、このようになっているのでしょうか。町会なりに働きかけをして、その点は町会によって配備の状況がかなり違うので、どう考えられているのかについても伺いたいと思います。","respondent":"山本防災課長、五十嵐災害対策担当課長","answer":"場合によっては、町会によって隊を２つ結成していれば２台配備している。そういった考え方で伺っているところです。 可搬ポンプの取扱いについて、お答えします。それにつきましては、基本的に区民消火隊の方々は、地域の消防団の方と連携して取扱いについて学び、訓練をされているのが実情です。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ミニポンプ隊を作っていきたいとか、そういう区としての考えは何かあるのか、伺いたいと思います。区としてどのように意識的に取り組んでいて、これからどうしていこうとしているのかという辺りを、少しお聞かせいただきたい。","respondent":"山本防災課長","answer":"それから、ミニポンプ隊を結成している部分に配備しているところで、そういった隊がない町会もあると認識はしています。有効的な利用はできないと考えていますので、考え方としては、自治会に配備すると考えているところです。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"防災公園が１つもなくて、また、ぜひ防災公園を意識的に造るという取組みを区としてもしていただきたいと思うのです。もう一度、その点について伺いたいと思います。","respondent":"藤田防災まちづくり部長","answer":"まだまだ公園の数は足りないと考えてございまして、特に町会の中に公園等がないところについては、やはり優先的に確保していくべきと考えています。あそこにいい土地があるよというお話があれば、そういう声を頂きながら、積極的に進めていきたいと考えています。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区民避難所のところで、ワンタッチ型の間仕切りですか、それもコロナ対策で配備したというご説明だったかと思います。そこら辺のところで、必要数、どんなものが、どれくらい配備されているのか、伺いたいと思います。","respondent":"平原防災体制整備担当課長","answer":"当初のご説明のとおりですけれども、原則学校に入れるという考えの下でやってありますが、スペースの関係を考えながら進めているところです。もう一点、配備数ですけれども、現状、ワンタッチ型の簡易間仕切りについては、区内全域で１,２００セットを備蓄しています。","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"あのようなところには、簡易間仕切りなども置けるということになっていくのでしょうか。備蓄倉庫として活用する方針というか、考え方があるのか、その点についても伺います。","respondent":"平原防災体制整備担当課長","answer":"それで、必要数は、その２倍の数に対応できるようにということで、１,２００セットを用意させていただいてあります。これからも検討途上ですけれども、新型コロナウイルスの陽性者に対する対応、訓練も進んでいるところです。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今、テレビなどで放映されている避難所でも、かなり間仕切りやテントが進んできているなという思いがしています。品川区として、ぜひ震災の対応としても、間仕切りというのはしっかりと備蓄をするようにお願いをしておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"湯澤委員","kind":"質問","question":"私からは、職員向けの訓練について、少しお尋ねしたいです。縮小したり、個別訓練等を行ったりしたのかを教えてほしいと求めました。","respondent":"五十嵐災害対策担当課長、滝澤災害対策担当部長","answer":"職員向けの訓練がコロナ禍でどうだったのかというご質問ですけれども、縮小はしておりません。ソーシャルディスタンスをとりながら訓練を実施しております。 職員向けですけれども、実際、今、災害対策担当課長からありましたように、全て実施しております。必要性と可能性がありまして、今、そこを探りながらも実施をしているという状況です。","id":"exchange-030"},{"speaker":"湯澤委員","kind":"質問","question":"それぞれご担当される職員の方々がきちんと扱えるような訓練をされているのかというところも教えていければと思います。例えば、誰もが分かるのかなと思うのですけれども、そういった取組みをされているのかも教えてほしいと求めました。","respondent":"平原防災体制整備担当課長","answer":"お答えでありましたとおり、自治会の方に周知という形で、このような訓練をやりましたよというご紹介を広報させていただいたところです。今後とも、そういった新たに入るものにつきましては、確実に周知、広報するとともに、使い方についての訓練を続けていきたいと考えています。","id":"exchange-031"},{"speaker":"湯澤委員","kind":"質問・要望","question":"備蓄物資の輸送手段についても少しお尋ねしたいです。まさに共助によって、避難所にいる区民の方が協力して物資を運ぶという計画なのか、それを教えてほしいと求めました。","respondent":"平原防災体制整備担当課長","answer":"５２か所の各避難所への供給ルートを設定いたしまして、例えば、確実に避難所まで行くという体制を整えていきたいと思います。共助でして頂くのは、避難所まで行ったところの荷下ろし作業と配付作業をお願いしようと考えています。","id":"exchange-032"},{"speaker":"湯澤委員","kind":"質問・要望","question":"区のホームページでも閲覧できると思いますので、普及啓発に努めていただいて、多くの区民に知っていただきたいなと考えています。松澤委員からもお話がありましたけれども、区職員向けの訓練を大変充実してやられているということなので、引き続き行ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"小芝委員","kind":"質問","question":"飲料用水の場合は、１日、１人当たり３リットルを基本とされているということです。西大井広場が２５０立方メートルということだと、大体何人ぐらいの方を対象に、均一にどのぐらいの量を供給する予定なのか説明を求めました。","respondent":"平原防災体制整備担当課長","answer":"ペットボトルだけで全て対応するということではなく、各学校についております、災害時の給水の遮断弁といったものを活用して水を確保しています。","id":"exchange-034"},{"speaker":"小芝委員","kind":"質問","question":"五丁目の方も多分いらっしゃると思うのですが、そういうところで、なかなかこの広場まで行くのが困難な方もいらっしゃると思います。そういったところへも支援などをお願いしたいなと思うのですけれども、お考えがあれば、説明を求めました。","respondent":"平原防災体制整備担当課長","answer":"３日分で１０８万リットル必要ですけれども、現状では４８０万リットルを準備させていただいておりまして、量的には足りているところです。災害時における水の全体像をいろいろ勘案しながら、今、お話のございました井戸の在り方も含めて研究を進めてまいりたいと考えています。","id":"exchange-035"},{"speaker":"大沢副委員長","kind":"確認","question":"とりわけ高齢者の方、女性の方、そして、子どもたち、そこの運用指針というか、国では内閣府等々で、都も出しております。品川区独自のものがあるのか、それに準拠した運用指針なるものがあるのか、そこのところだけ確認させてください。","respondent":"平原防災体制整備担当課長","answer":"災害時のトイレですけれども、ご指摘のとおり、国等々からは指針が出ているところです。こういったものがありますというご紹介の段階にとどまっておりまして、例えば、どのような順番でという指針までは至っていない現状です。","id":"exchange-036"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"安全性の確保ということでも聞いておりますので、そこはきちんと考慮に入れながら、このトイレのところは扱ってほしいと求めました。答弁は要りません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/822771?Template=document&Id=6606#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":35730,"voices":94}},{"id":"r03-20211208-10","meetingId":"r03-cm12","date":"2021年12月8日","dateIso":"2021-12-08","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時５８分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を2件整理しています。","topics":[{"id":"topic-01","title":"令和３年第４回定例会","agenda":"令和３年第４回定例会","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"この６６号議案は、児童センターの老朽化に伴う改修工事にあたってというもので、本来、文教委員会で賛成すべきところ、誤って反対してしまいました。共産党としては、６６号議案については賛成させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"東京都後期高齢者医療広域連合議会の報告","agenda":"東京都後期高齢者医療広域連合議会の報告","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"一言、後期高齢者医療広域連合議会におきまして、来年度の保険料の値上げが報告されていると思います。住民負担が重くなっている中、保険料引上げは行うべきではないと、意見だけ述べさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/861371?Template=document&Id=5434#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":9182,"voices":28}},{"id":"r03-20211209-9","meetingId":"r03-cm12","date":"2021年12月9日","dateIso":"2021-12-09","committee":"文教委員会","time":"午前１０時４８分～午前１１時４２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件整理しています。","topics":[{"id":"topic-01","title":"第８８号議案 令和３年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第８８号議案 令和３年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"その中身について伺いたいと思います。残りの１６歳以上１８歳以下の子どもには、いつどのように支給する考えなのか、伺いたいと思います。","respondent":"伊東子育て応援課長","answer":"収入額で見ますと、標準世帯で年収９６０万円以下の方が対象となって、それを超える方に関しては対象外という形になります。１６歳から１８歳までに関しましては、申請が必要になるという話をしたところですけれども、年明けというか来年から作業に入るという予定です。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回、補正予算を組んで、なぜ子育て世帯のみの給付でとどめるのでしょうか。これまでも求めてまいりましたけれども、区独自に支給すべきではないかと思いますけれども、いかがか尋ねました。","respondent":"伊東子育て応援課長","answer":"今回、子育て世帯への臨時特別給付ということで、国がそういう方針を決めまして、我々はそれに基づいて粛々と進めていくです。そういうことで、区としてさらに別の形ということは、今は考えていないという状況です。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"３点伺いたいのですけれども、１つは、うち現金で全額支給してほしいという要望はどれぐらいあったのかというのを伺いたいです。３点目は、品川区も１０万円を現金で支給すべきなのではないかと思うのですけれども、いかがか尋ねました。","respondent":"伊東子育て応援課長","answer":"それはお答えできませんが、聞いている範囲の中で言えば、現金を希望するなどというような意見が出ていることは承知しています。５万円分現金支給ということで作業を進めているわけですけれども、具体的に国から、こちらとしてはそれを待ってからということになります。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"現金でも可能とするということを言っているわけですから、そのほうが早いですから一番よかったのですけれども、ちょっと難しいということであれば。なので、様々な面からも、やはりクーポンよりも現金ということをぜひ選択していただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"それで、具体的に国から、こうするようにと示されたときには、それにそのまま従ってしまうということなのでしょうか。その辺についてお考えを伺いたいと思います。","respondent":"伊東子育て応援課長","answer":"ですので、それを見た上で、どうするかというのは考えていかなくてはいけないのかと。まだ今のところ、はっきりとしたものは示されていないという状況で、何ともお答えできないかという感じです。","id":"exchange-005"},{"speaker":"吉田委員","kind":"質問・要望","question":"子育てで、皆さん実感されていると思いますけれども、例えば食費などはどうなのでしょうかと思います。ぜひ区としての判断もそこに加味していただきたいと思うのですが、その辺についてもう一回、お考えを伺いたいと思います。","respondent":"伊東子育て応援課長","answer":"それを見て、品川区としてどう考えていくかというのは、当然判断していかなくてはいけないと思います。子育てに限定したクーポン券がいいのか、現金がいいのかというのは、もう少し具体的なことを見ないと判断できないのかと思っているところです。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"いろいろな区としての経費削減の意味もありますし、そのように検討していただきたいということ、これは要望でとどめます。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"松本委員","kind":"質問","question":"今、すごくそこは大事なところだと思うので伺いたいのですけれども、今の地域の実情に合わせてというところがありました。そこが今できないのは、まだ政府から、実情に合わせてというところの詳しい内容が出てきていないからということでよろしいのか尋ねました。","respondent":"伊東子育て応援課長","answer":"そもそも１１月２６日だったのですけれども、現金５万円の部分について、もう年内支給に向けて取り組めという話があったところです。その時点で１０万円一括という話は全く考えていなかったところでございまして、今は５万円の先行給付に集中している状況です。","id":"exchange-008"},{"speaker":"松本委員","kind":"質問","question":"この時点で、では先行の部分と残りの部分をどうするのかという検討は可能であったのではないかと思うのですけれども、そこは検討されなかったのか。それで、検討されなかった理由として、もう一度伺いますけれども、実情の部分というのが示されなかったからと理解してよろしいのか尋ねました。","respondent":"伊東子育て応援課長","answer":"確かに、１１月２６日の段階の通知は、広い意味で子育て世帯の、後半の５万円の部分を含めた形の通知です。こちらとしては、触れられてはいますけれども先のことだという判断で、現在に至っているということです。","id":"exchange-009"},{"speaker":"松本委員","kind":"質問","question":"これはまた、これからの議論ですごく重要になってくる点だと思うのですけれども、今回の先行の５万円、そして後々のクーポン券。もう一度、趣旨のところ、どのように政府から説明されているのか伺います。","respondent":"伊東子育て応援課長","answer":"我が国の子供たちを力強く支援し、子育て世帯を支援する取組の一つとして、一時金的に支給するものだというような趣旨です。もっと広く言えば、先ほどのクーポンの話に出てくるかと思うのですけれども、一応、先行給付に関しては、このようなことで進めさせていただいたです。","id":"exchange-010"},{"speaker":"松本委員","kind":"質問","question":"我が国の子供たちを力強く支援し、その未来を拓く観点から、児童を養育している云々となっているわけです。区としての見解を伺わないといけないのですけれども、そういったものは、この趣旨には含まれていないと理解してよろしいか尋ねました。","respondent":"伊東子育て応援課長","answer":"１１月２６日の、地域の実情に応じた様々なことが考えられるから、それは自治体のほうでという話は書かれていたところです。後段の５万円の部分、なかなか国の方針が決定していないということもありますので、もう少し通知を待たないといけないかです。","id":"exchange-011"},{"speaker":"松本委員","kind":"確認","question":"趣旨はあくまで子育て世帯の支援であるというところはきちんと確認した上で考えていかなければならないと思っています。その上で、もう少し具体的にお伺いしたいのがコールセンターですけれども、このコールセンターはいつからいつまで開設する予定か尋ねました。","respondent":"伊東子育て応援課長","answer":"１２月中旬、通知するタイミングに合わせて開設しようと考えています。期限につきましては、取りあえず現状で、年度末までに支給という話になってありますので、そこで一旦の契約をしようかと考えておるところです。","id":"exchange-012"},{"speaker":"松本委員","kind":"質問","question":"その契約の中には、今後追加で出てくるクーポンですけれども、このクーポンについての問合せも契約の中に含まれていると考えていいのか尋ねました。","respondent":"伊東子育て応援課長","answer":"大きな意味で、先ほど委員がおっしゃった１０万円支給という部分の事業ですので、当然そこの部分、そのとき決まっているかどうかという部分はありますけれども、問合せには対応するという契約をしようと考えています。","id":"exchange-013"},{"speaker":"松本委員","kind":"質問","question":"年内に５万円給付して、業務の内容としてコールセンターに入っていったとしても、予算額としては変わらないと考えていいのか尋ねました。","respondent":"伊東子育て応援課長","answer":"今、３月３１日と言ったのは、先行給付分の部分での一定のめどが立つということで、当初の契約はそういうふうにしようと思っているところです。ですので、今後の展開によっては、契約延長や契約変更など、様々別のことを考えていかなくてはいけないかと思っています。","id":"exchange-014"},{"speaker":"松本委員","kind":"確認","question":"ここの部分は今、確認できたかと思います。これは、５万円振り込むのか１０万円振り込むのかで、振込手数料というのは変わるのか尋ねました。","respondent":"伊東子育て応援課長","answer":"金額だけでは、５万円、１０万円での金額で、単価の変更はなかったと考えていますので、当然、振込のところだけ考えれば変わらないかと思っています。","id":"exchange-015"},{"speaker":"松本委員","kind":"確認","question":"１回であれば１回分の振込手数料で終わるということも確認できたかと思います。この辺りの想定は今どうなっているのか尋ねました。","respondent":"伊東子育て応援課長","answer":"クーポン発行という形になると、３月などというのは非常に、個人的にというか私的には厳しいのかと思っています。遅くとも６月ぐらいまでにはということが言われていたかと思うのですけれども、いろいろ大変、時間がかかるかと思っています。","id":"exchange-016"},{"speaker":"松本委員","kind":"質問","question":"卒業式や入学式や新学期というふうな話でしたけれども、今お伺いしたところでは、６月という話が政府から出ているということだと思います。この点について、区から国に対して、これは少しおかしいのではないかというふうな話というのはされていないのか尋ねました。","respondent":"伊東子育て応援課長","answer":"どういう進捗ですか、検討を始めましたかみたいな話は、問合せが来ているところです。それで今後の話が変わっていくのかどうか分かりませんけれども、そういう中での動きはあるという状況です。","id":"exchange-017"},{"speaker":"松本委員","kind":"質問・要望","question":"最後に要望ですけれども、以上伺ったところでも、何とか年内に一括で１０万円できることを要望いたしまして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"松澤委員","kind":"質問・要望","question":"いろいろお話が出たので簡潔に、要望みたいな形で言わせていただきたいのですけれども、私も現金給付を希望しております。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"つる委員","kind":"質問・要望","question":"今、各委員のご質疑を伺っていて理解したところもありますが、まず、そもそもの前提の数字をいろいろ、この際なので教えていただきたいと思うのです。子どもたちに対する応援になるような仕組みというのが一番求められるところだろうという中での、いろんな変化がなされているという理解があります。","respondent":"伊東子育て応援課長","answer":"区が把握しているというところでの児童手当、特例給付も含むというところで、人数的に言いますと、４万６,６７７人というのが、給付準備で拾った数字となっています。","id":"exchange-020"},{"speaker":"つる委員","kind":"質問・要望","question":"まとめて伺うと、来年の３月までに出生が予定されている人数、そこの人数の想定というのは何人なのでしょうか。それと併せて、先ほどご答弁いただいた４万６,６７７人の中での特例給付の人数を説明を求めました。","respondent":"伊東子育て応援課長","answer":"出生見込みですけれども、１,５００人程度いたというところで、１,５００名を見込んだところです。同じく区でやっている部分のところですけれども、１万７,６３５名というのが、先ほど言った９月の段階の数字という形になります。","id":"exchange-021"},{"speaker":"つる委員","kind":"確認","question":"１万５,０００世帯とか、そのぐらいが、いわゆる子育て世帯の中で今回の支給対象外の人数なのかと。これは事前に確認できなかったので、どういう仕組みで、そこについて詳しく教えてほしいと求めました。","respondent":"伊東子育て応援課長","answer":"在勤庁、官公署から直接支給されているという形になりまして、区としてそれの正確な数字や情報を把握しているわけではないという形になります。結果的に申請いただくのですけれども、在勤庁から一斉に周知していただいて、各自治体に申請していただくという形になります。","id":"exchange-022"},{"speaker":"つる委員","kind":"確認","question":"では、ごめんなさい。確認で、お願いします。","respondent":"伊東子育て応援課長","answer":"勤め先、私が今、品川区役所に勤めていて、子どもがいるという形になれば、品川区役所から児童手当が、所得の関係で出ているという形になりますので、区や省庁、いろいろな公務員がいらっしゃいますけれども、所属しているところから手当が支給されているという形です。","id":"exchange-023"},{"speaker":"つる委員","kind":"確認","question":"１点、通知のところでの確認をしていただいたとは思うのですが、既にもう自治体の判断でということが出てきているわけです。これまで言われているところの、自治体の判断で現金給付もですとか、その方法は柔軟にという、その根拠の文書というのはあるのか尋ねました。","respondent":"伊東子育て応援課長","answer":"今の、自治体の判断でというところに関しては、自治体でそれぞれ創意工夫して、実施に向けて準備しろというような通知は来ているところですけれども、その中で、やはり細かい部分での要領が示されていないので、いろいろと示された段階で質問したいというように考えております。","id":"exchange-024"},{"speaker":"つる委員","kind":"確認","question":"１６歳から１８歳、いわゆる高校生世代というのでしょうか、現金５万円。ただ現金の５万円についてのタイミングというのは、年度内に５万円というのは、いくことなのか尋ねました。","respondent":"伊東子育て応援課長","answer":"２回目として、その人に対して支給するという形になりますので、時間的には年度内で。年度内までの申請ということになっていますので、若干遅くなるかもしれないですけれども、割と早い時期に可能なのかとは思っています。","id":"exchange-025"},{"speaker":"つる委員","kind":"質問","question":"これは今回挙げられている対象の３万３,４４６人に、一括という表現かどうか分からないですけれども、支給されるということでいいのですか。申請ではないので、そういう理解でよろしいか尋ねました。","respondent":"伊東子育て応援課長","answer":"対象の３万３,４４６人には、それで最終的に支給するという形になりますので、そういう流れになっています。","id":"exchange-026"},{"speaker":"つる委員","kind":"提案","question":"先ほど来確認させていただいた自治体の判断、この場でですけれども、ぜひ要望しておきたいと思います。これは、ほかの会派と一緒で要望にとどめますけれども、そういったことを最後に要望させていただいて、質疑を終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"安藤委員","kind":"意見","question":"賛成です。様々改善すべき点はあると思いますけれども、今回の補正予算の中身は、コロナ禍の下での子育て支援に必要なものですので賛成いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"吉田委員","kind":"質問・要望","question":"本当に具体的にこの給付があれば、あのうちは助かると、頭に浮かんでしまうおうちもあります。ですので、今後の子育て世帯への応援策についてはもう少し検討してほしいと求めましたが、この給付については賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"松本委員","kind":"質問・要望","question":"そこは改めて要望したいところではありますが、やはり今日の各会派のご意見を伺っていても、やはり基本はクーポンなのだという話をする。今回の国の在り方というところについては、いろいろと意見を言っていただきたいと要望いたしまして、賛成と述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/247429?Template=document&Id=5052#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":15930,"voices":69}},{"id":"r03-20211209-5","meetingId":"r03-cm12","date":"2021年12月9日","dateIso":"2021-12-09","committee":"総務委員会","time":"午前１１時５０分～午後 ０時１４分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を11件整理しています。","topics":[{"id":"topic-01","title":"説明に入る前に、所管委員会における審査結果","agenda":"説明に入る前に、所管委員会における審査結果","exchanges":[{"speaker":"おくの委員","kind":"提案","question":"品川区もクーポンではなく、５万円を現金で給付することを考えるべきではないかと思うのですけれども、その点いかがお考えでしょうか。この２点をお尋ねしたいと思いますとの意見を述べました。","respondent":"黒田財政課長","answer":"それに対応した補正予算です。いわゆる５万円相当のクーポン給付事業につきましては、こちらは今回の５万円と違いまして、適切に対応してまいりたいと考えているところです。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問・要望","question":"それから、予備費の枠内の範囲だし、国で審議されている最中ということですが、品川区自身はどのようにお考えでしょうか。今の景気の状況、あるいは財政出動の必要性、今回の国の範囲では狭過ぎるのではないかということですけれども、どのようにお考えか尋ねました。","respondent":"黒田財政課長","answer":"５万円のクーポン相当事業と言われていますのは、既に予備費で編成された部分については、早急に補正予算を編成するというものです。事情に応じて対応するためには財源も必要となりますので、適宜対応していくというところでございまして、その方針は今後も変更ございません。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問・要望","question":"それが政治・経済を預かる者の使命だと思いますので、どうぞよろしくお願いいたします。意見、要望ということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"結果だけではなく、どういう議論があったかということも報告を受けたいと思います。説明や意見、質問なども出ていたと思うので、そういうふうに委員会の運営をぜひ検討していただければというのを要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問","question":"文教委員会の傍聴に行ったのですけれども、まず、歳出の中の、コールセンター運営等委託について、文教委員会でも質疑がありました。その中で気になったのが、コールセンター運営等委託がどのような契約になっているのかというところを伺いたいのですけれども……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"田中委員","kind":"意見","question":"それで、文教委員会の質疑の中でも、委託についての契約の中身というのが、きちんと答弁されていなくて、随意なのかプロポーザルなのか。そういうところも分からなかったので、答えられる範囲で、分かる範囲でお答えいただければとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"田中委員","kind":"確認","question":"今回は１５歳までの子育て世帯に現金の給付で、今後は１６歳以上の子どもたちに、生活者ネットワークももちろん現金給付がよいという立場です。ぜひ現金の方向に進んでいってほしいと思うのですけれども、多分、そういった検討がされていたのかどうかというところを確認させてください。","respondent":"渡辺委員長、黒田財政課長","answer":"前段のことだけ。本件事業と、その先のクーポン券等はまた別の事業となりますので、それを前提に、見込みを踏まえた答弁をお願いします。２段階になるのではないかというお尋ねですが、今決まっている国予算の予備費を活用して行う事業ですので、これは早急に対応しなければならないです。","id":"exchange-007"},{"speaker":"田中委員","kind":"確認","question":"ですので、区としてぜひそういう検討をしていただきたかったということを聞きたかったのです。よかったら、その辺について、検討されたのかされていないのかだけ確認させてください。","respondent":"黒田財政課長","answer":"繰り返しになりますが、今回の事業は、国で予算措置されているものに対して対応しますので、これは早急に対応する。２段階一括とありますが、次に言われている５万円相当のクーポン給付事業は、そこに関して区で何かができるということではないと考えております。","id":"exchange-008"},{"speaker":"渡部委員","kind":"質問・要望","question":"マスコミが１０万円を５万円と５万円というので、何といったらいいのですか、本当のところがうまく伝わっていないような気がします。ですから、その前段分の５万円が今回支給になるということが明確に分かるような体制を取っていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問・要望","question":"品川区で１０万円、全国の自治体も要望しているのですから、次のことも品川区として考えてほしいと求めました。今回の補正に関しては、先ほど申し上げましたが、国から来た子育て世帯臨時特別給付金ですから、これに対して異議はございません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"たけうち副委員長","kind":"質問・要望","question":"１つは、子育て世帯臨時特別給付金ですから、わきまえておかないといけないのかと。国としてやっているわけですから、いろいろ区も検討していただければということを要望させていただいて、意見で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/740650?Template=document&Id=2218#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":8439,"voices":45}},{"id":"r03-20211209-10","meetingId":"r03-cm12","date":"2021年12月9日","dateIso":"2021-12-09","committee":"議会運営委員会","time":"午後 １時４５分～午後 １時４６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/861371?Template=document&Id=5436#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":931,"voices":8}},{"id":"r03-20211223-7","meetingId":"r03-cm12","date":"2021年12月23日","dateIso":"2021-12-23","committee":"厚生委員会","time":"午後 １時０７分～午後 １時５５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件整理しています。","topics":[{"id":"topic-01","title":"第８９号議案、令和３年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第８９号議案、令和３年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"令和３年１月以降、令和３年１月以降に毎月低い収入が続いているということではなくて、一月でもそういう月があったら対象者になるということか尋ねました。","respondent":"櫻木生活福祉課長","answer":"１か月分の収入の書類のご提出をもって、それを１２倍したところで非課税相当かどうかを判定するということになりますので、１か月分で足りるということになっております。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"ぱっと分かる人はそんなに多くないのではないかなと思うのですけれども、分かりやすい資料というか、そうしたものを区としては出していただけるのか。要は、対象なのにもらえない人が生まれないために、どういう工夫がされるのかなというのをお聞きしたいと思います。","respondent":"櫻木生活福祉課長","answer":"ぜひコールセンターにお電話していただいて、いろいろご相談していただければ、分かるような状態になると考えています。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そこはもうちょっと工夫できないものかなと思うのですけれども、ポスターとか広報とか、ほかにはどういったことを。今後もっと工夫していただきたいと思うのですけれども、いかがか尋ねました。","respondent":"櫻木生活福祉課長","answer":"今後、区のほうでも進めていきたいと思っていますが、可能であれば介護事業者等のご協力を頂きながら進めていければと考えています。その際には、当然ながら周知等も含めて、届くような形で進められればと考えています。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"とにかく対象なのにもらえない方が出ないようにというのは強く求めておきたいなと思うのですけれども、家計急変世帯が４,０００世帯ということで、何を根拠に出された数なのか尋ねました。","respondent":"櫻木生活福祉課長","answer":"こちらの数字につきましては、都のほうから、家計急変世帯数の予算や様々な施策の検討に当たっての目安として、非課税世帯数の７％程度という数値が示されておりますので、それに基づいて推計したものです。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"東京都が出してきたいろいろな中から出されてきたということですけれども、これがもし４,０００世帯を超える場合の対応はどうなるのですか。４,０００世帯で終わりではなく、そこは対応していただけるということになるのか尋ねました。","respondent":"櫻木生活福祉課長","answer":"こちらにつきましては、予算が足りなくなったということであれば、国の補助等の関係もありますが、基本的には補正予算を新たにお願いして措置していくという形になるのかなと考えております。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"どう数字を持ってきているのかなと思って、私もそうかなという方は問合せなりができるので、やはり周知のところはすごく大事だなと改めて思います。それで、申請書等々、返送先や申請先というのは生活福祉課のところでとありますけれども、申請書はダウンロードできるものになっていますか尋ねました。","respondent":"櫻木生活福祉課長","answer":"実は申請書の正式な様式等は、国のほうからまだ確認できない状況ではあるのですが、これまでの経緯を見ますと、ダウンロードできるような形でご提供できればと考えています。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"確認","question":"そこの確認と、生活保護の基準ラインで見ると対象になるとか、そういう分かりやすいものでもないのですか。伺いたいと思います。","respondent":"櫻木生活福祉課長","answer":"１つ目のお尋ねとしては、非課税世帯数のほうに生活保護世帯は入るということで、支給対象となっております。２点目のお尋ねとしましては、扶養人数が何人とか、そういう形で計算されるものです。","id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"確認","question":"２月中に非課税世帯へ確認書を送付されて受付開始となっていて、受付次第、給付は順々に進んでいくということでいいですか。２月中旬に非課税世帯の方のものを受け付けたら、２月下旬、３月初旬あたりに一番早い人だと支給されるということでいいのか尋ねました。","respondent":"櫻木生活福祉課長","answer":"私どもの目標感としては、そのような形で着金ができるように努力してまいりたいと考えています。","id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それなので、来年の課税のところで非課税になりそうだという方々が対象だということで基本的に考えていいでしょうかということと、それから。そこのところがイメージできるような形でご説明いただけたらありがたいです。","respondent":"櫻木生活福祉課長","answer":"国から示されている収入額ベースで申し上げると、配偶者・扶養家族計１名を扶養している場合は１５６万円というような目安が示されてあります。コロナの影響を受けて収入が減少したことというのがポイントになりますので、そちらの要件を満たすことも必要となります。","id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"生活保護は、今回の１０万円というのはもちろん収入とみなされないということで確認させてほしいと求めましたので、その点についても伺います。この間、一般質問で伺ったときも、具体的にどういう方かというのは暮らし・しごと応援センターでもつかまれていると思うのです。","respondent":"櫻木生活福祉課長","answer":"品川区社会福祉協議会へもそのような形でご案内するよう、今後依頼していこうと考えています。現時点では様々な事業者から情報提供いただいて話を伺っているところですので、事業者について、まだ決まっているところはございません。","id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"もう１つ、家計急変世帯相談受付開始というのがありますけれども、これは相談をしてから受け付けるということになっていくのか、それとも、自分は対象になるなと思ったら、ホームページからダウンロードして郵送という形でしてもいいのか、その点についても伺いたいと思います。","respondent":"櫻木生活福祉課長","answer":"書類等をご自身で記入して、書類も全部ご自身でご用意できる方であれば、当然郵送していただければと考えています。ちょっと相談しながら何が必要かみたいなお話が必要であれば、相談窓口でお話しいただければと考えています。","id":"exchange-011"},{"speaker":"若林委員","kind":"質問・要望","question":"これに１２を掛けると１５６万円になるというようなところの分かりやすい周知というのですか、お知らせをしていただきたいなと思うのですが。そういう方々も対象になるわけですから、三点具体的に申し上げましたけれども、そこら辺も含めてどういうふうに思いますか。","respondent":"櫻木生活福祉課長","answer":"可能な限り簡素な方法で対応させていただければと考えています。ＤＶに関してですが、幾つか要件を満たす方につきましては、例えば品川区で支給ができるという取扱いの考え方は示されております。","id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"ここについてはどういうご答弁になるか。できれば触っていただきたいなというお願いというか、思いがありますので、この点についてご答弁ほしいと求めました。","respondent":"櫻木生活福祉課長","answer":"過去の品川区社会福祉協議会利用者等について、どういう形で周知していくかという点につきましては、品川区社会福祉協議会とも話をしながら、周知方法については考えていければと考えています。","id":"exchange-013"},{"speaker":"せお委員","kind":"質問・要望","question":"ほかの委員が質問されていて、ほとんど理解したのですけれども、細かいところを２点ほど。そういったところとか、ちょっと細かいのですけれども、教えてほしいと求めました。","respondent":"櫻木生活福祉課長","answer":"１点目のお亡くなりになって家計が急変したのだけれども、都や国等を通じて疑義照会するような形になろうかと思います。配慮が必要な方については個別的な対応を考えておりまして、どういう形で申請書等をお渡ししていくかというのは検討してまいりたいと考えています。","id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"確認","question":"対象の方に支給されるのが、来年度の５月に非課税世帯の方は受付終了だから、その後になるわけですね。支給される時期が、非課税世帯の方はいつぐらいなのか、家計急変世帯の方はいつぐらいなのかというのをまず確認します。","respondent":"櫻木生活福祉課長","answer":"順次お支払いしていく流れになるかと考えていますので、２月下旬から３月上旬での着金を目標にして、それ以降は順次入金されていくという流れになるかと考えています。","id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"質問","question":"要するに、年度をまたがないように支給をするという形、でもないですか。それを超えたときに、決算をどういうふうにするか分からないので、残したままのものはどういう形になるのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"確認","question":"今回だって、１０万円、江戸川区は早いなとかとなるではないですか。品川区がこうやっていったときに、このスケジュールで、遅いと言われないですよねという確認。","respondent":"櫻木生活福祉課長","answer":"他区の状況につきましては、各区検討中というところで話は聞いているところです。２月中、２月下旬という想定の区もあると聞いておりますので、できるだけ早期に実施できるよう努めてまいりたいと考えています。","id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"意見","question":"もちろん着実にというのが一番大切なことなので、それはそのとおりにやってもらいたいのだけれども、ぜひ区民の方から遅いと言われることが我々の耳にあまり入らないように、との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"やはり今まででかなりの方々の相談を受けているわけですから、その方々のところに周知されるように、改めてぜひお願いしておきたいと思います。ぜひその２か所のところはこれまでの相談の方にということでお願いしたいと思うのですけれども、改めてよろしいか尋ねました。","respondent":"櫻木生活福祉課長","answer":"もちろんできるだけ、手段はあれですけれども、周知は図ってまいりたいと思っています。尽力をしつつ、申請状況等を見ながら、周知方法について適切に考えていきたいと思っています。","id":"exchange-019"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そういったところではなく、コロナで苦しむ国民の暮らしの応援に充てるべきだと思いますし、それを区としても国に求めてほしいと求めました。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/715198?Template=document&Id=3616#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":13459,"voices":59}},{"id":"r03-20211223-9","meetingId":"r03-cm12","date":"2021年12月23日","dateIso":"2021-12-23","committee":"文教委員会","time":"午後 １時１０分～午後 ２時１２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件整理しています。","topics":[{"id":"topic-01","title":"第８９号議案、令和３年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第８９号議案、令和３年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"つる委員","kind":"質問・要望","question":"１６歳から１８歳もできる限り早い時期にということ等、緊急要望させていただいて、まず推進するということをお伝えさせていただきたいなと思います。既に中学生以下で児童手当の対象となっているというのは把握されているわけですから、給付されるのかどうかというところをまず確認させてください。","respondent":"伊東子育て応援課長","answer":"児童手当を受給されている世帯で、兄弟関係で１６歳から１８歳の上の子もいるというところですけれども、今回２８日の支給に際しましては、この方々、兄弟関係がいる場合は、その部分も含めまして支給していくということで作業を進めております。","id":"exchange-001"},{"speaker":"つる委員","kind":"確認","question":"１０万円・１０万円、今のお話の対象となる兄弟がいる世帯の人数なのでしょうか、その把握というのは今現在できているのでしょうか。もしできているのであれば、３,９４０名のうち、何人というのでしょうか、何世帯というのでしょうか、その数字を説明を求めました。","respondent":"伊東子育て応援課長","answer":"前段のほうは、兄弟分も含めて一括支給という形になります。今拾っているのが１,７３９名、世帯数でいうと１,６３９世帯ということで、拾った数字は１,７３９名です。","id":"exchange-002"},{"speaker":"つる委員","kind":"確認","question":"確認で、２,２０１人で、世帯はどのぐらいになるのでしょうか。説明を求めました。","respondent":"伊東子育て応援課長","answer":"そもそも、最初の計算上には、ここで一括支給する、しないにかかわらず計算しておりましたので、１６歳から１８歳ということで単純に計算していたところですので、今回そこにその部分が入るということは、引かれるという考え方でいいかなと思います。","id":"exchange-003"},{"speaker":"つる委員","kind":"質問","question":"伺ったのは、引き算の２,２０１人の、世帯では何世帯あるのでしょうか。分かれば説明を求めました。","respondent":"伊東子育て応援課長","answer":"すみません。今、数字的なものを探し切れておりません。","id":"exchange-004"},{"speaker":"つる委員","kind":"確認","question":"その世帯が対象世帯かどうかという確認をする書類等、職員の皆さんのそうした確認作業の処理能力だとか件数、これが今。５,１０５人の方がどんと一括で来たときに、確認作業ができた上で入力等して、ごめんなさい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"つる委員","kind":"質問・要望","question":"支給のタイミングですね。この辺りが分かれば教えてほしいと求めました。","respondent":"伊東子育て応援課長","answer":"３週間弱ですかね、最短で。というようなスケジュール感かなと思っています。","id":"exchange-006"},{"speaker":"つる委員","kind":"質問・要望","question":"国の制度ですからしっかり議論していくという一定のことはあるわけですが、親子に支給していくというふうに対応している自治体もあるわけです。もしくは、そうでなければ、どういうふうに考えているとかあれば説明を求めました。","respondent":"伊東子育て応援課長","answer":"委員ご指摘のとおり、今、基準日が設けられておりまして、９月３０日ということになります。国の示されている制度の中で動いておりますので、今のところ、そこに対しての対応というのは考えていないという状況です。","id":"exchange-007"},{"speaker":"つる委員","kind":"質問・要望","question":"ある自治体で確認した中では、そういう形でも給付の在り方、やり方をいろいろ工夫することを考えている自治体もあるようなのです。ですから、これは別で取っていただきたいと思うのですが、改めてご答弁ほしいと求めました。","respondent":"伊東子育て応援課長","answer":"今、国のつくったスキームの中でやってくださいよという話、それに対して資金的な部分は国から出しますよという話になったところです。明石市に限らず、現時点で品川区としては、国が決めた範囲の中での給付ということで進めていくです。","id":"exchange-008"},{"speaker":"つる委員","kind":"質問・要望","question":"これは要望します。明石市は、報道ベースで見ると、対象世帯に対しては数字としては非常に少ないのですけれども、数字がもし把握できているのであれば説明を求めました。","respondent":"伊東子育て応援課長","answer":"すみません。離婚している数につきましては、調べておりません。","id":"exchange-009"},{"speaker":"松本委員","kind":"確認","question":"確かに１２月２３日現在で申請してくれというのは難しいと思うのですけれども、国なのかあれですけれども、９月３０日が基準日になっている。９月３０日以降１２月２３日までの間に別居を理由として児童手当の振込口座を変えている、そういう世帯があるかどうか、そこを確認したいと思います。","respondent":"伊東子育て応援課長","answer":"児童手当制度の中の口座変更ですとか様々な変更というのは、その都度、ご本人の状況に応じて申請されていると認識しております。","id":"exchange-010"},{"speaker":"松本委員","kind":"質問","question":"この９月３０日の基準日というのは、これは国が示したものなのでしょうか。お願いします。","respondent":"伊東子育て応援課長","answer":"国のほうで基準日を設けて、その時点で、簡単に言うと、住所要件的にはどっちに行くかというところで、その市区町村で給付するというのが前提です。","id":"exchange-011"},{"speaker":"松本委員","kind":"質問","question":"現実に児童手当を振り込んでいるところになるわけですから、それをやってしまうと、国から今回の国庫支出金が出ないという話なのでしょうか。１０月以降の口座に振り込んでしまったら国庫支出金が出ないのか、出るけれどもやらないのか、これはどっちなのか尋ねました。","respondent":"伊東子育て応援課長","answer":"それは児童手当制度の中でということでは決められております。単純に言えば、プラスアルファで何か出しますよとか、そういう部分に関しては見ませんよというような話です。","id":"exchange-012"},{"speaker":"松本委員","kind":"質問","question":"であれば、少なくとも１０月以降に切り替えている世帯については、ぎりぎり、基準日をもっと遅らせるとかやりようがあると思うのですけれども、手続が必要とかではなく、切り替えている世帯については切替え後のほうに振り込むべきだと思うのですが、そこのご見解はいかがか尋ねました。","respondent":"伊東子育て応援課長","answer":"口座情報だけに関して言えば、変更後の口座ということになります。","id":"exchange-013"},{"speaker":"松本委員","kind":"質問・要望","question":"ご答弁いただきたいのだけれども、１０月になって口座を切り替えた人たちのところには、切替え後の口座にお金が入るということでよろしいでしょうか。確認いたします。","respondent":"伊東子育て応援課長","answer":"そのとおりです。","id":"exchange-014"},{"speaker":"松本委員","kind":"質問・要望","question":"ここについては、先ほどのつる委員のご指摘のとおりだと思うので、ここは重複するので、これは要望して、こちらももっと早くできればと思っています。最終的には２０日のタイミングで決定が出ているかと思うのですけれども、そこの流れのところ、どういう流れでこの意思決定が行われたのか伺います。","respondent":"伊東子育て応援課長","answer":"１５日ですけれども、実質的には１６日に目に触れたというところではありますが、企画部門を交えまして内部的な検討を進めてきたところです。","id":"exchange-015"},{"speaker":"松本委員","kind":"質問","question":"恐らく１６日に把握されて、２０日までの５日の間に、どのタイミングで現金で一括でいこうということが内部的にほぼ決まったのか。そこの部分はどのタイミングなのか尋ねました。","respondent":"伊東子育て応援課長","answer":"クーポンから現金化というのは割と早い段階、１６日というか、その段階です。いろいろなところの確認作業を進める中で、何とかいけそうだということで、年内一括というような方向に決まったと。","id":"exchange-016"},{"speaker":"松本委員","kind":"確認","question":"どういう確認をしたいかというと、１６日のタイミングで、もうちょっと混乱が少なかったのかなと個人的には思うのです。今回の１６日から２０日の流れの中で、区長がこうするべきではなかろうかという意見を述べたことというのはあるのか尋ねました。","respondent":"伊東子育て応援課長","answer":"私が直接ということではございませんけれども、その都度、企画部門から報告といいますか、意見を仰いでいると認識しております。","id":"exchange-017"},{"speaker":"松本委員","kind":"質問","question":"ここはやはりしっかりと、行政側が報告して動いたのか、それとも区長がきちんとリーダーシップを取ったのかというのは大事だと思うので、明確にしたいのですけれども、区長から年内現金一括給付でという意見は出たのか尋ねました。","respondent":"柏原子ども未来部長","answer":"それは今まで我々の認識にはなかったところなので、それであれば、他の自治体もそれで動けそうだというのが見えてきました。これは通常の意思決定もそういう流れですが、そういう流れになって、そのタイミングが２０日のタイミングになっていたとご理解ください。","id":"exchange-018"},{"speaker":"松本委員","kind":"確認","question":"ちょっと細かい確認になってしまって申し訳なかったですが、確かにおっしゃるとおり、贈与契約のところは、それは流れとしてあるのかなと思います。改めて今回、１６歳から１８歳の部分とは別に郵送する必要があったのかなかったのか、そこの部分を確認したいと思います。","respondent":"伊東子育て応援課長","answer":"今回この議決が通りましたらば、今度、１０万円で支給しますという通知は出します。ということで、その部分は必要というところになります。","id":"exchange-019"},{"speaker":"松本委員","kind":"確認","question":"加えて確認なのですけれども、今回の補正予算説明書の事項別明細書を確認すると、システム改修費等になっているのです。コールセンター運営等委託のほうが計上されていたのですけれども、今回のシステム改修費等の「等」に何が含まれるのか、お願いいたします。","respondent":"伊東子育て応援課長","answer":"システム改修費と、いわゆる消耗品関係と……、そうですね。消耗品関係……、役務費は別立てですので、一般事務費と委託料ということです。","id":"exchange-020"},{"speaker":"松本委員","kind":"質問","question":"では、コールセンターのところは、追加ではかからなかったという理解でよろしいのか尋ねました。","respondent":"伊東子育て応援課長","answer":"コールセンターに関しましては、前回の補正の中での資金で、その中での手当てということになります。","id":"exchange-021"},{"speaker":"松本委員","kind":"確認","question":"確認が取れましたので、この年末の中で皆さん本当に大変な作業だったと思います。厳しい追及になったことをおわびしつつ、いろいろと問題はあると思いますので、引き続きどうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"つる委員","kind":"確認","question":"松本委員のところで確認をしていただいた部分があるのですが、１０月に入ってから口座変更等がある場合とかとあって、予算の中から充てられると。１０万円の給付は、８月末で確認した口座以外を対象とした場合には、国の財源は出さないと。","respondent":"伊東子育て応援課長","answer":"ある程度、国が決めた中に関しては、国庫補助ということで出しますという形になっています。いろいろな別の形でやるところに関しては、独自財源なり、今おっしゃったような財源を使っていいというような話だったのかなと思っているところです。","id":"exchange-023"},{"speaker":"つる委員","kind":"確認","question":"ありがとうございました。国からのそういう通知等も確認していただいて、ぜひ柔軟な、寛大な対応を改めてお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"吉田委員","kind":"確認","question":"質疑の中でいろいろ確認できたのですけれども、どうしても私たちが気になっているのは、身を潜めてＤＶから逃げている方たちなのです。今も制度というか、あるのだと思うのですけれども、改めて伺いたいのですが、いかがでしょう。","respondent":"伊東子育て応援課長","answer":"給付金関係につながるというような形だと思うのですけれども、一般的な広報というか、啓発活動をしているということです。","id":"exchange-025"},{"speaker":"吉田委員","kind":"確認","question":"男女共同参画センターのほうだと何度も確認はしているのですけれども、そのことも含めて相談を受けたときには、もうやっておられるのでしょうか。その辺、説明を求めました。","respondent":"伊東子育て応援課長","answer":"今回の給付金に関して言えば、それぞれにこういう形で徹底というか周知してくださいというお知らせというか、文書は届いているということです。ですので、そこが入り口になって、つながるという形になろうかと思います。","id":"exchange-026"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。ぜひ直接の相談窓口に、ぜひそちらに相談してみてくださいというのを情報提供していただくようにお願いして、これは要望でとどめておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"松澤委員","kind":"質問・要望","question":"１６歳から１８歳、なるべく早くお願いしたいという要望とともに、そこの部分というのは本当に大切なことではないかなと改めて感じました。子どもにきちんと届くようなさらなる工夫を要望しまして、意見とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"つる委員","kind":"質問・要望","question":"意見は、先ほど質疑させていただいて確認させていただきました。積極的な対応を、他自治体のいい事例を参考にしていただいて、ぜひ品川区らしい工夫をやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"区民要望を受けた全ての会派から、残り５万円も現金で給付をという意見が出されたということで、現金給付を決断した区に敬意を表したいと思います。実際に支援事業を行っている、学生ですとか若者への支援も併せて行うべきだと思っておりまして、引き続きぜひ検討していただきたいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"吉田委員","kind":"意見","question":"年内はそうは言っても難しいかなと思っておりましたが、今回一括で現金で給付されるということで、本当に賛成いたします。それから相談窓口への周知も含めて、適正に子育て世帯に渡るような制度にしていただくことを前提として、賛成いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"松本委員","kind":"質問・要望","question":"今日いろいろ確認させていただいて、１０万円振り込まれないとなると、そこの部分が最後の問題として残っているのかなと思います。そこの部分は何とかしていただきたいなと要望いたしますが、いずれにせよ、今回については本当に国政のほうが物すごい大混乱だったと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/247429?Template=document&Id=5054#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":19464,"voices":68}},{"id":"r03-20211223-5","meetingId":"r03-cm12","date":"2021年12月23日","dateIso":"2021-12-23","committee":"総務委員会","time":"午後 ２時２０分～午後 ２時４７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件整理しています。","topics":[{"id":"topic-01","title":"説明に入る前に、所管委員会における審査結果","agenda":"説明に入る前に、所管委員会における審査結果","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"１０万円全額現金で給付されるということになるので、１０万円全額現金給付ということは求めたことなので、非常に歓迎したいです。そのときにも申し上げたのですけれど、依然として狭過ぎるという点に関して、区の認識およびお考えをいま一度お伺いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"特に狭いという面でも、営業・事業面への支援がないというところが一つの特徴だろうと思います。特にこの辺りの認識、お考えをお伺いしたいと思います。","respondent":"黒田財政課長","answer":"区のほうでも取り組んでおりますし、国のほうも大型の補正予算を組んでおりますので、そういった中で全体的な支援をしていくものと考えています。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問・要望","question":"これから予算を組む場面ですし、また、あるいは上乗せで家賃支援給付金なんかもやったことがあります。そういうふうに区独自の姿勢も示すことができるわけですから、いろいろ考えていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"９月１日以降に離婚したりで非親権者となった親に給付されたり、その辺、どうなのでしょうか。これは子育てのために今回給付するという事業ですが、その辺についてどのような考えでいらっしゃるのか、それだけ説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問・要望","question":"そして、約５分後には総務委員会の開始時間になってしまったので、ぜひ報告をしてほしいということは要望したいと思います。子育て応援費のほうも生活保護費のほうも周知がとても重要だと思うので、そこの区としての考え方を伺いたいのですけれども、いかがか尋ねました。","respondent":"黒田財政課長","answer":"１点目の契約の件ですが、まずはどのようにすれば早く事務が進められるかという観点で、これから取り組んでいくものと考えています。２点目の家計急変世帯等への周知、また、該当される方が申請されるようにということで取り組んでまいりたいと思ってあります。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"図書館だったり公園とか、ぜひ目につくところでしていただきたいなということを要望したいのですが、いかがでしょうか。随意契約だったりとかという、そこだけを知りたいのですが、教えていただけますか尋ねました。","respondent":"黒田財政課長","answer":"所管のほうで広く伝わるようにということで、様々な方法で周知していくようにということで、こちらは所管に伝えてまいりたいと思います。予算成立後に事務を行いますので、所管で検討していると思いますが、現時点で私からはお答えできないです。","id":"exchange-006"},{"speaker":"渡部委員","kind":"質問・要望","question":"確認させていただきたい点が、人事のほうは、ある程度給付が落ち着くまでの時限で、なおかつ兼任でやっていくのでしょうか。確認したいのは、分かれば教えてほしいなというところだけ、すみません。","respondent":"佐藤（憲）企画調整課長","answer":"臨時給付金に係る体制と人事についてのご質問ですが、まず、全庁体制で業務を進める、迅速かつ確実に給付を行うということが基本的な考え方です。組織も設置しておりますので、異動といいますか、そういった形も今後進めていかなければならないと考えております。","id":"exchange-007"},{"speaker":"たけうち副委員長","kind":"質問・要望","question":"一括で年内に振り込んでいただけるということも確認していますので、年明け早々、対応していただけるということを伺っておりますので。その辺も踏まえて、なるべく大変な方を一人でも多く対応していけるような形で、ぜひ頑張っていただきたいなと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"賛成しますが、意見を言わせてください。対象者の方が気づくことのできる徹底した周知、本当に困っている方に届くような周知をお願いしたいと要望しまして、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/740650?Template=document&Id=2220#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":9137,"voices":44}},{"id":"r03-20211223-10","meetingId":"r03-cm12","date":"2021年12月23日","dateIso":"2021-12-23","committee":"議会運営委員会","time":"午後 ３時４０分～午後 ３時４１分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/861371?Template=document&Id=5440#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":908,"voices":8}}]);
